window.QSBI_LESSONS=window.QSBI_LESSONS||{};QSBI_LESSONS[3]=[{"id":"03_19","g":3,"l":19,"topic":"Сюжетная реклама и сторителлинг","module":"Реклама","format":"Комбинированный","skills":["Креативность","Критическое мышление","Презентация"],"goal":"К концу урока ученик сможет объяснить, почему история в рекламе запоминается лучше простого перечисления, и назвать её 3 части — герой, проблема, решение — на примере ролика.","criteria":["Я называю 3 части рекламной истории.","Я нахожу героя, проблему и решение в примере ролика.","Я объясняю, почему история запоминается лучше списка свойств."],"result":"Раскадровка рекламного ролика из 3 кадров «герой — проблема — решение» для товара и короткое объяснение, почему её запомнят.","stages":[{"stage":"Разминка «Угадай слово»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Реклама (advertising)","real":"Сообщение о товаре, которое приглашает его купить","shown":"Сообщение о товаре, которое приглашает его купить","truth":true,"first":"Р"},{"term":"Сторителлинг (storytelling)","real":"Рассказ истории, чтобы её запомнили и почувствовали","shown":"Рисунки по кадрам, как будет выглядеть ролик","truth":false,"first":"С"},{"term":"Рекламный ролик","real":"Короткое видео (15–60 секунд) о товаре или услуге","shown":"Короткое видео (15–60 секунд) о товаре или услуге","truth":true,"first":"Р"},{"term":"Сюжет","real":"Что происходит в истории по порядку","shown":"Рассказ истории, чтобы её запомнили и почувствовали","truth":false,"first":"С"},{"term":"Герой","real":"Главный персонаж, с которым зритель себя сравнивает","shown":"Главный персонаж, с которым зритель себя сравнивает","truth":true,"first":"Г"},{"term":"Раскадровка","real":"Рисунки по кадрам, как будет выглядеть ролик","shown":"Что происходит в истории по порядку","truth":false,"first":"Р"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Реклама (advertising)","def":"Сообщение о товаре, которое приглашает его купить"},{"term":"Сторителлинг (storytelling)","def":"Рассказ истории, чтобы её запомнили и почувствовали"},{"term":"Рекламный ролик","def":"Короткое видео (15–60 секунд) о товаре или услуге"},{"term":"Сюжет","def":"Что происходит в истории по порядку"},{"term":"Герой","def":"Главный персонаж, с которым зритель себя сравнивает"},{"term":"Раскадровка","def":"Рисунки по кадрам, как будет выглядеть ролик"}],"english":"advertising — реклама; storytelling — сторителлинг","concepts":{"head":"Понятия","items":["Рекламный ролик — короткое видео о товаре.","Сюжетная реклама рассказывает историю (storytelling): герой, проблема, решение.","Раскадровка — план ролика в рисунках."]},"steps":{"head":"Почему история работает, по шагам","items":["Зритель видит героя, похожего на себя, — ему интересно","У героя проблема — зритель переживает","Появляется товар и решает проблему — зритель радуется","Чувство связывается с товаром — его запоминают. Список «красный, лёгкий, прочный» вызывает меньше чувств, поэтому забывается быстрее"]},"scheme":"Три кадра-прямоугольника: «Герой» → «Проблема» → «Решение (товар)» и под ними четвёртый: «Слоган + логотип». Сбоку надпись «15–30 секунд».","examples":[{"lab":"Казахстан","text":"Авиакомпания Air Astana в своих роликах показывает путешествия по Казахстану и"},{"lab":"Миру","text":"Герой мечтает увидеть новое место, и полёт помогает мечте сбыться."},{"lab":"Пример класса","text":"«Мальчик Ерасыл опаздывает в школу, потому что не слышит будильник (проблема). Новый будильник с песней домбры будит его весело (решение)». Цена будильника — 900 тенге."},{"lab":"Мир","text":"С 1931 года художник Хэддон Сандблом рисовал Санта-Клауса для рекламы Coca-Cola, и праздничные истории с ним запомнились людям во многих странах."}],"mistake":{"myth":"Товар показывают с первой секунды, а истории нет — получается просто перечисление","fix":"Переставить кадры и спросить, когда зрителю становится интересно."},"check":[{"q":"Какие 3 части у рекламной истории?","a":"Герой, проблема, решение"},{"q":"Почему зритель запоминает историю?","a":"Он сопереживает герою"},{"q":"Где в ролике появляется товар?","a":"В решении"}],"kz":{"text":"Air Astana — национальная авиакомпания Казахстана. В её рекламе часто показывают красоту Казахстана и истории путешественников, а не только цены на билеты.","link":"история о мечте и путешествии запоминается лучше, чем список рейсов."},"world":{"text":"С 1931 года художник Хэддон Сандблом рисовал Санта-Клауса для рекламы Coca-Cola, и эти праздничные истории увидели люди во многих странах мира. Сегодня компании рассказывают истории в роликах на разных языках, чтобы их поняли везде.","link":""},"fact":"Образ доброго Санта-Клауса в красной шубе стал особенно популярным благодаря рекламе Coca-Cola: художник Хэддон Сандблом рисовал его для компании с 1931 года больше 30 лет.","cards":[{"n":"1","title":"Найди части истории","lines":["Ролик: «Девочка Аружан идёт в поход. Начинается дождь, рюкзак промокает, тетрадь с рисунками мокнет. Папа дарит ей рюкзак-непромокайку. В следующем походе дождь, но рисунки сухие, Аружан улыбается. Надпись: “Рюкзак Дала — сухо в любую погоду”».","Герой: ____ Проблема: ____ Решение: ____ Слоган: ____","Ответы для тренера: Аружан; рюкзак промокает; рюкзак-непромокайка; «Сухо в любую погоду»."],"hand":"Сдать: ответы.","answers":[]},{"n":"2","title":"Раскадровка нашего ролика (advertising)","lines":["Товар: ____ (будильник, термос, фонарик, рюкзак — на выбор).","Кадр 1. Герой: кто он?","Кадр 2. Проблема: что случилось?","Кадр 3. Решение: как помог товар?","Кадр 4. Слоган и цена (до 1000 тенге)."],"hand":"Сдать: раскадровку.","answers":[]}],"practice":[{"type":"scene","title":"Реклама-история","minutes":7,"setting":"Команда разыгрывает рекламу-историю про зонт: герой, проблема, решение.","roles":[{"name":"Герой","task":"Идёшь в школу в новой одежде."},{"name":"Дождь","task":"Начинаешь «лить» (шуршишь руками)."},{"name":"Продавец зонтов","task":"Появляешься с решением — зонтом."},{"name":"Диктор","task":"Говоришь слоган в конце."}],"steps":["Герой идёт.","Начинается дождь — проблема.","Появляется зонт — решение.","Диктор говорит слоган."],"freeze":["Стоп-кадр! Кто герой, какая проблема, какое решение?"],"twist":"Поворот: у героя нет денег на зонт. Как изменить историю?","debrief":["Почему история запоминается лучше списка свойств?"]},{"type":"scene","title":"Скучная и интересная реклама","minutes":6,"setting":"Два продавца рекламируют один сок: один перечисляет свойства, другой рассказывает историю.","roles":[{"name":"Продавец-перечислитель","task":"Говоришь: «Сок. Яблочный. 1 литр. Вкусный.»"},{"name":"Продавец-рассказчик","task":"Рассказываешь историю про бабушкин сад."},{"name":"Зритель","task":"Выбираешь, какую рекламу запомнил."}],"steps":["Перечислитель рекламирует.","Рассказчик рекламирует.","Зритель выбирает."],"freeze":["Стоп-кадр! Какая реклама запомнилась?"],"twist":null,"debrief":["Что делает рекламу интересной?"]},{"type":"scene","title":"Найди героя","minutes":5,"setting":"Учитель описывает рекламу, класс находит героя, проблему и решение.","roles":[{"name":"Ведущий","task":"Описываешь рекламный ролик."},{"name":"Класс","task":"Показываете на пальцах: 1 — герой, 2 — проблема, 3 — решение."}],"steps":["Описание.","Поиск частей."],"freeze":["Стоп-кадр! Где проблема?"],"twist":null,"debrief":["Из каких 3 частей состоит рекламная история?"]}],"homework":"Посмотреть с родителями один рекламный ролик и найти в нём героя, проблему и решение.","support":"Готовые герои и проблемы на выбор, шаблон раскадровки с подписями кадров.","advanced":"Добавить к раскадровке слоган до 5 слов и придумать, как изменить историю для 15-секундного ролика.","photo":{"src":"lessons/img/03_19.jpg","author":"Robert Likovszki","q":["Что вы видите на фото? Как это связано с нашей темой?","Какая история понятна детям любой страны без слов?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g03-l19.pptx","name":"19. Сюжетная реклама и сторителлинг (3 кл).pptx","mb":1.5}},{"id":"03_20","g":3,"l":20,"topic":"Сюжетная реклама и сторителлинг: практикум","module":"Реклама","format":"Проектная мастерская","skills":["Креативность","Командная работа","Презентация"],"goal":"К концу урока ученик сможет придумать в тройке короткую рекламную историю о товаре по схеме «герой — проблема — решение» и рассказать или разыграть её за 1 минуту.","criteria":["В моей истории есть герой, проблема и решение.","Я рассказываю или играю свою роль понятно и вовремя.","Я заканчиваю историю слоганом и ценой товара."],"result":"Сценарий-раскадровка рекламной истории тройки и её показ (рассказ или сценка) за 1 минуту со слоганом и ценой.","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Реклама (advertising)","real":"Сообщение о товаре, которое приглашает его купить","shown":"Сообщение о товаре, которое приглашает его купить","truth":true,"first":"Р"},{"term":"Сторителлинг (storytelling)","real":"Рассказ истории, чтобы её запомнили","shown":"Сколько денег можно потратить","truth":false,"first":"С"},{"term":"Сценарий","real":"Текст, где записано, кто что говорит и делает","shown":"Текст, где записано, кто что говорит и делает","truth":true,"first":"С"},{"term":"Слоган","real":"Короткая запоминающаяся фраза о товаре","shown":"Рассказ истории, чтобы её запомнили","truth":false,"first":"С"},{"term":"Роль","real":"Персонаж, которого играет ученик","shown":"Персонаж, которого играет ученик","truth":true,"first":"Р"},{"term":"Бюджет","real":"Сколько денег можно потратить","shown":"Короткая запоминающаяся фраза о товаре","truth":false,"first":"Б"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Реклама (advertising)","def":"Сообщение о товаре, которое приглашает его купить"},{"term":"Сторителлинг (storytelling)","def":"Рассказ истории, чтобы её запомнили"},{"term":"Сценарий","def":"Текст, где записано, кто что говорит и делает"},{"term":"Слоган","def":"Короткая запоминающаяся фраза о товаре"},{"term":"Роль","def":"Персонаж, которого играет ученик"},{"term":"Бюджет","def":"Сколько денег можно потратить"}],"english":"advertising — реклама; storytelling — сторителлинг","concepts":{"head":"Понятия","items":["Рекламная история (storytelling) — короткий рассказ: герой, проблема, решение.","Сценарий — план: кто что говорит.","Слоган — фраза до 5 слов.","Роль — кого играешь."]},"steps":{"head":"Как сделать историю за урок, по шагам","items":["Вытянуть карточку товара","Решить, кто покупатель, и сделать его героем","Придумать проблему, понятную покупателю","Показать, как товар её решает","Придумать слоган","Распределить роли: герой, «товар» или помощник, рассказчик","Отрепетировать и уложиться в 1 минуту"]},"scheme":"Таблица сценария: «Кадр | Кто говорит | Что делает | Слова». Под ней — таймер «60 секунд»: 15 секунд герой, 20 — проблема, 20 — решение, 5 — слоган.","examples":[{"lab":"Казахстан","text":"Товар «термос». Герой — чабан в зимней степи; проблема — чай быстро остывает; решение — термос держит чай горячим целый день; слоган «Тепло в любую погоду»; цена 900 тенге."},{"lab":"Расчёт бюджета ролика","text":"Камера на час — 300 тенге, костюм — 200 тенге, монтаж — 400 тенге: 300 + 200 + 400 = 900 тенге."},{"lab":"Мир","text":"Многие компании снимают истории о своих товарах, где главный герой — обычный человек, похожий на покупателя."}],"mistake":{"myth":"История длинная, с лишними героями, и не укладывается в минуту","fix":"Вычеркнуть всё, что не связано с проблемой и решением, и прорепетировать с таймером."},"check":[{"q":"Кто должен быть героем?","a":"Человек, похожий на покупателя"},{"q":"Где звучит слоган?","a":"В конце"},{"q":"Камера 300, костюм 200, монтаж 400 — сколько стоит ролик?","a":"900 тенге"}],"kz":{"text":"Казахские сказки и истории об Алдаре Косе — хитром и находчивом герое — знает каждый ребёнок в Казахстане.","link":"у этих историй тоже есть герой, проблема и находчивое решение, поэтому их помнят много лет."},"world":{"text":"Рекламные истории о простых людях снимают во многих странах, потому что зрители узнают в герое себя. Международные компании переводят такие истории на разные языки и меняют детали, чтобы они были понятны в каждой стране.","link":""},"fact":"Слово «слоган» происходит от гэльского «sluagh-ghairm» — так называли боевой клич шотландских кланов; позже так стали называть короткие запоминающиеся фразы в рекламе.","cards":[{"n":"1","title":"Сценарий рекламной истории (storytelling)","lines":["Товар: ____ Покупатель: ____","Кадр 1 (герой): кто? Слова: ____","Кадр 2 (проблема): что случилось? Слова: ____","Кадр 3 (решение): как помог товар? Слова: ____","Кадр 4: слоган (до 5 слов) и цена (до 1000 тенге): ____","Роли: герой — ___, помощник — ___, рассказчик — ___."],"hand":"Сдать: сценарий.","answers":[]},{"n":"2","title":"Бюджет ролика","lines":["Камера на час — 300 тенге. Костюм — 200 тенге. Музыка — 100 тенге. Монтаж — 400 тенге.","Задача 1: камера + костюм + монтаж = ?","Задача 2: бюджет 1000 тенге. Хватит ли на всё?","Задача 3: что убрать, чтобы осталось 200 тенге на листовки?"],"hand":"Сдать: решения.","answers":[["Задача 1","900 тенге."],["Задача 2","300 + 200 + 100 + 400 = 1000 — хватит ровно."],["Задача 3","Например, костюм."]]},{"n":"3","title":"Товары для жеребьёвки","lines":["Термос, фонарик, будильник с домброй, непромокаемый рюкзак, светоотражающий браслет, шарф из верблюжьей шерсти."],"hand":"Сдать: вытянутую карточку вместе со сценарием.","answers":[]}],"practice":[{"type":"scene","title":"Снимаем ролик","minutes":8,"setting":"Команда снимает рекламный ролик своего товара по сценарию.","roles":[{"name":"Режиссёр","task":"Командуешь: «Мотор! Снято!»"},{"name":"Герой","task":"Играешь главную роль."},{"name":"Оператор","task":"«Снимаешь» рамкой из рук."},{"name":"Диктор","task":"Произносишь слоган и цену."}],"steps":["Режиссёр объясняет сцену.","Команда играет.","Диктор говорит слоган и цену."],"freeze":["Стоп-кадр! Понятно ли, что продаём?"],"twist":"Поворот: ролик должен быть короче — всего 15 секунд. Что убрать?","debrief":["Что обязательно должно быть в ролике?"]},{"type":"scene","title":"Дубль два","minutes":6,"setting":"Режиссёр просит переснять: в первом дубле не было слогана.","roles":[{"name":"Режиссёр","task":"Объясняешь, что исправить."},{"name":"Актёры","task":"Играете снова лучше."}],"steps":["Дубль 1.","Замечание.","Дубль 2."],"freeze":["Стоп-кадр! Что стало лучше?"],"twist":null,"debrief":["Зачем пересматривать работу?"]},{"type":"scene","title":"Слоган за 30 секунд","minutes":5,"setting":"Команды придумывают короткий слоган.","roles":[{"name":"Команда","task":"Придумываете слоган до 5 слов."},{"name":"Жюри","task":"Выбираете самый запоминающийся."}],"steps":["Придумываем.","Читаем вслух.","Голосуем."],"freeze":["Стоп-кадр! Почему он запоминается?"],"twist":null,"debrief":["Каким должен быть слоган?"]}],"homework":"Рассказать рекламную историю тройки родителям и спросить, запомнили ли они слоган через час.","support":"Готовый сценарий с пропусками и роль рассказчика, у которого есть текст.","advanced":"Переделать историю в версию на 15 секунд и придумать второй слоган.","photo":{"src":"lessons/img/03_20.jpg","author":"Danae Paparis","q":["Что вы видите на фото? Как это связано с нашей темой?","Что нужно изменить в нашей истории, чтобы её поняли дети в Японии?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g03-l20.pptx","name":"20. Сюжетная реклама и сторителлинг — практикум (3 кл).pptx","mb":1.6}},{"id":"03_21","g":3,"l":21,"topic":"Реклама, которая не сработала: разбор","module":"Реклама","format":"Комбинированный","skills":["Критическое мышление","Креативность"],"goal":"К концу урока ученик сможет найти в рекламном кейсе одну главную ошибку (не та целевая аудитория, непонятное сообщение или неправда) и предложить, как её исправить.","criteria":["Я нахожу ошибку в рекламе и называю её.","Я определяю, для какой целевой аудитории нужна эта реклама.","Я предлагаю исправление и объясняю, почему оно сработает."],"result":"Лист разбора кейса: найденная ошибка рекламы, для какой целевой аудитории она должна быть и исправленный вариант (заголовок или картинка).","stages":[{"stage":"Разминка «Правда или ловушка?»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Реклама (advertising)","real":"Сообщение о товаре, которое приглашает его купить","shown":"Сообщение о товаре, которое приглашает его купить","truth":true,"first":"Р"},{"term":"Целевая аудитория","real":"Люди, для которых сделан товар и которым показывают рекламу","shown":"Дело, которое делает товары или услуги для людей","truth":false,"first":"Ц"},{"term":"Кейс","real":"Реальная или учебная история, которую разбирают, чтобы научиться","shown":"Реальная или учебная история, которую разбирают, чтобы научиться","truth":true,"first":"К"},{"term":"Брейнсторминг","real":"«мозговой штурм»: команда быстро предлагает много идей без критики","shown":"Люди, для которых сделан товар и которым показывают рекламу","truth":false,"first":"Б"},{"term":"Сообщение рекламы","real":"Главная мысль, которую реклама хочет сказать","shown":"Главная мысль, которую реклама хочет сказать","truth":true,"first":"С"},{"term":"Бизнес (business)","real":"Дело, которое делает товары или услуги для людей","shown":"«мозговой штурм»: команда быстро предлагает много идей без критики","truth":false,"first":"Б"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Реклама (advertising)","def":"Сообщение о товаре, которое приглашает его купить"},{"term":"Целевая аудитория","def":"Люди, для которых сделан товар и которым показывают рекламу"},{"term":"Кейс","def":"Реальная или учебная история, которую разбирают, чтобы научиться"},{"term":"Брейнсторминг","def":"«мозговой штурм»: команда быстро предлагает много идей без критики"},{"term":"Сообщение рекламы","def":"Главная мысль, которую реклама хочет сказать"},{"term":"Бизнес (business)","def":"Дело, которое делает товары или услуги для людей"}],"english":"advertising — реклама; business — бизнес","concepts":{"head":"Понятия","items":["Целевая аудитория (ЦА) — те, кому нужен товар: например, первоклассники, мамы малышей, спортсмены.","Кейс — история для разбора.","Брейнсторминг — много идей без критики."]},"steps":{"head":"Почему реклама не срабатывает, по шагам проверки","items":["Для кого реклама? Если игрушку рекламируют в газете для пенсионеров — не та ЦА","Понятно ли сообщение за 3 секунды?","Правда ли то, что обещают?","Есть ли цена, место и призыв?","Найти главную ошибку и предложить исправление"]},"scheme":"«Детектор ошибок»: 4 лампочки — «Кому?», «Понятно?», «Правда?», «Что делать?». Под каждой — пример ошибки и исправления.","examples":[{"lab":"Казахстан","text":"Казахстан (учебный кейс): кафе в Шымкенте повесило рекламу детского праздника на остановке у завода в 6 утра, где ездят только рабочие. Повесили 50 плакатов по 20 тенге — потратили 1000 тенге, а пришли только 2 семьи. Ошибка — не та ЦА; исправление — повесить у школ и детских садов."},{"lab":"Мир","text":"В 1985 году компания Coca-Cola изменила вкус напитка и запустила рекламу «новой колы», но покупатели хотели старый вкус, и через 79 дней компания вернула прежний напиток."}],"mistake":{"myth":"«реклама не сработала, потому что некрасивая» — ученики судят только по картинке","fix":"Пройти все 4 лампочки; часто проблема в аудитории или в отсутствии цены и призыва."},"check":[{"q":"Что такое целевая аудитория?","a":"Люди, которым нужен товар"},{"q":"Где рекламировать кружок робототехники для третьеклассников?","a":"В школе, в родительских чатах"},{"q":"50 плакатов по 20 тенге — сколько потратили?","a":"1000 тенге"}],"kz":{"text":"Kolesa.kz — казахстанский сайт объявлений о продаже автомобилей. Почему?»","link":"его реклама обращена к целевой аудитории — водителям и тем, кто хочет купить или продать машину, а не к детям."},"world":{"text":"В 1985 году компания Coca-Cola в США изменила вкус своего напитка и сделала большую рекламу «новой колы», но покупатели были недовольны и требовали вернуть старый вкус. Через 79 дней компания вернула прежний напиток.","link":""},"fact":"«Новую колу» (New Coke) компания Coca-Cola выпустила в апреле 1985 года, а уже в июле вернула прежний напиток под названием Coca-Cola Classic из-за жалоб покупателей.","cards":[{"n":"1","title":"Кейсы неудачной рекламы","lines":["Кейс А. Кафе устроило детский праздник и повесило 50 плакатов по 20 тенге на остановке у завода в 6 утра. Пришли 2 семьи. (Ошибка: не та ЦА.)","Кейс Б. Листовка магазина игрушек: мелкий текст на 20 строк, нет адреса и цены. (Ошибка: непонятно, что делать.)","Кейс В. Реклама рюкзака: «Не промокает никогда!» Покупатели вернули 30 рюкзаков после первого дождя. (Ошибка: неправда.)","Кейс Г. Реклама кружка шахмат с картинкой футбольного мяча. (Ошибка: непонятное сообщение.)"],"hand":"Сдать: выбранный кейс.","answers":[]},{"n":"2","title":"Лист разбора","lines":["Наш кейс: ____","Какая лампочка «горит»: Кому? / Понятно? / Правда? / Что делать?","Целевая аудитория (для кого реклама): ____","Наше исправление (заголовок или картинка): ____","Почему сработает: ____","Расчёт: сколько потратили в кейсе А?"],"hand":"Сдать: лист разбора.","answers":[["","50 × 20 = 1000 тенге."]]}],"practice":[{"type":"scene","title":"Реклама для никого","minutes":7,"setting":"Рекламщик рекламирует игрушки пенсионерам и удивляется, что никто не покупает.","roles":[{"name":"Рекламщик","task":"Рекламируешь игрушечную машинку бабушкам и дедушкам."},{"name":"Бабушка","task":"Не понимаешь, зачем тебе машинка."},{"name":"Ребёнок","task":"Очень хочешь машинку, но тебе рекламу не показали."}],"steps":["Рекламщик рекламирует.","Бабушка удивляется.","Ребёнок говорит: «А мне не показали!»"],"freeze":["Стоп-кадр! В чём ошибка рекламы?"],"twist":"Поворот: бабушка вспоминает, что у неё есть внук. Как переделать рекламу для неё?","debrief":["Что такое целевая аудитория?"]},{"type":"scene","title":"Мелкий шрифт","minutes":6,"setting":"На рекламе крупно написано «Скидка!», а очень мелко — «только сегодня в 6 утра».","roles":[{"name":"Покупатель","task":"Пришёл за скидкой и удивлён."},{"name":"Продавец","task":"Показываешь мелкий шрифт."},{"name":"Защитник покупателей","task":"Объясняешь, почему это нечестно."}],"steps":["Покупатель приходит.","Продавец показывает условия.","Защитник объясняет."],"freeze":["Стоп-кадр! Честная ли это реклама?"],"twist":null,"debrief":["Какая реклама честная?"]},{"type":"scene","title":"Исправь рекламу","minutes":5,"setting":"Команда получает плохую рекламу и исправляет её.","roles":[{"name":"Критик","task":"Находишь ошибку."},{"name":"Исправитель","task":"Предлагаешь исправление."}],"steps":["Читаем рекламу.","Ищем ошибку.","Исправляем."],"freeze":["Стоп-кадр! Почему исправление сработает?"],"twist":null,"debrief":["Как найти ошибку в рекламе?"]}],"homework":"Найти одну рекламу на улице или в интернете (с родителями) и определить её целевую аудиторию.","support":"Кейс с подсказкой «посмотри на лампочку “Кому?”» и готовые варианты исправлений на выбор.","advanced":"Посчитать, сколько денег потратили впустую в своём кейсе, и предложить, как сделать рекламу за меньшие деньги.","photo":{"src":"lessons/img/03_21.jpg","author":"Robert Likovszki","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему компании важно спросить покупателей, прежде чем менять товар?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g03-l21.pptx","name":"21. Реклама, которая не сработала — разбор (3 кл).pptx","mb":1.5}},{"id":"03_22","g":3,"l":22,"topic":"Реклама в интернете и у блогеров","module":"Реклама","format":"Комбинированный","skills":["Критическое мышление","Командная работа"],"goal":"К концу урока ученик сможет отличить рекламу у блогера от обычного видео по 3 признакам и объяснить, по какому признаку он это узнал.","criteria":["Я называю признаки рекламы у блогера.","Я определяю, реклама это или обычное видео, и объясняю почему.","Я знаю, что делать, если реклама скрыта."],"result":"Памятка команды «Как узнать рекламу у блогера» с 3–4 признаками и разбор 4 описаний видео: реклама или нет и почему.","stages":[{"stage":"Разминка «Угадай слово»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Реклама (advertising)","real":"Сообщение, которое приглашает купить товар","shown":"Сообщение, которое приглашает купить товар","truth":true,"first":"Р"},{"term":"Цифровой маркетинг","real":"Продвижение товаров в интернете: в приложениях, на сайтах, в видео","shown":"Все блоги и блогеры вместе","truth":false,"first":"Ц"},{"term":"Блог (blog)","real":"Страница или канал в интернете, где человек регулярно что-то показывает или рассказывает","shown":"Страница или канал в интернете, где человек регулярно что-то показывает или рассказывает","truth":true,"first":"Б"},{"term":"Блогер","real":"Человек, который ведёт блог","shown":"Продвижение товаров в интернете: в приложениях, на сайтах, в видео","truth":false,"first":"Б"},{"term":"Блогинг","real":"Занятие ведением блога","shown":"Занятие ведением блога","truth":true,"first":"Б"},{"term":"Блогосфера","real":"Все блоги и блогеры вместе","shown":"Человек, который ведёт блог","truth":false,"first":"Б"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Реклама (advertising)","def":"Сообщение, которое приглашает купить товар"},{"term":"Цифровой маркетинг","def":"Продвижение товаров в интернете: в приложениях, на сайтах, в видео"},{"term":"Блог (blog)","def":"Страница или канал в интернете, где человек регулярно что-то показывает или рассказывает"},{"term":"Блогер","def":"Человек, который ведёт блог"},{"term":"Блогинг","def":"Занятие ведением блога"},{"term":"Блогосфера","def":"Все блоги и блогеры вместе"},{"term":"Ютуб и ютубер","def":"Сайт для видео и человек, который снимает для него ролики"}],"english":"advertising — реклама; blog — блог","concepts":{"head":"Понятия","items":["Цифровой маркетинг — реклама в интернете: баннеры, реклама в приложениях, видео.","Блог (blog) — канал человека, блогер — его автор, блогосфера — все блоги.","Блогеры часто получают деньги или подарки от компаний за рассказ о товаре — это реклама (advertising)."]},"steps":{"head":"Как узнать рекламу, по шагам","items":["Есть ли надпись «Реклама», «#ad», «Спонсор», «При поддержке…»?","Блогер называет марку и много раз показывает упаковку?","Есть промокод, скидка или ссылка «купить»?","Говорит только хорошее и зовёт купить сейчас? Если 2 признака и больше — скорее всего, это реклама"]},"scheme":"«Светофор рекламы»: зелёный — обычное видео (нет марок, ссылок, промокодов); жёлтый — есть 1 признак, надо присмотреться; красный — 2 и более признака или надпись «Реклама».","examples":[{"lab":"Казахстан","text":"На детских каналах в интернете, например у телеканала «Балапан», рядом с мультфильмами может показываться реклама, и её отделяют от самих мультфильмов. Учебный"},{"lab":"Пример","text":"Блогер распаковывает конструктор, говорит «по моему промокоду скидка 500 тенге» и показывает ссылку — это реклама. Если конструктор стоит 3000 тенге, со скидкой — 2500 тенге."},{"lab":"Мир","text":"Во многих странах есть правила, по которым блогер обязан честно помечать рекламу словами «реклама» или «#ad»."}],"mistake":{"myth":"«Если блогер мне нравится, значит, он говорит правду, это не реклама»","fix":"Блогеру могут платить даже если он хороший; поэтому ищем признаки, а не верим «на слово»."},"check":[{"q":"Что такое блог?","a":"Канал или страница человека в интернете"},{"q":"Какой признак самый точный?","a":"Надпись «Реклама» или «Спонсор»"},{"q":"Конструктор 3000 тенге, скидка 500 — сколько платить?","a":"2500 тенге"}],"kz":{"text":"Детский телеканал «Балапан» — казахстанский канал с мультфильмами и передачами для детей, у него есть и интернет-канал. А в интернете?»","link":"на телевидении и в интернете реклама отделяется от передач, и дети учатся её отличать."},"world":{"text":"Во многих странах, например в США и странах Европы, есть правила: если блогеру заплатили за рассказ о товаре, он должен честно написать «реклама» или «#ad». Это нужно, чтобы зрители, особенно дети, понимали, где совет, а где реклама.","link":""},"fact":"Первое видео на YouTube — «Me at the zoo» («Я в зоопарке») — загрузил один из основателей сайта Джавед Карим 23 апреля 2005 года; ролик длится 19 секунд.","cards":[{"n":"1","title":"Реклама или нет?","lines":["Видео 1. Блогер рисует кота и показывает, как смешивать краски. Названий фирм нет.","Видео 2. В начале надпись «Реклама». Блогер рассказывает о новом самокате, говорит: «Переходите по ссылке».","Видео 3. Блогер распаковывает конструктор, 5 раз показывает коробку, говорит: «По моему промокоду скидка 500 тенге».","Видео 4. Блогер едет в Бурабай и рассказывает о природе; в конце: «Спасибо гостинице “…” за поддержку».","Задача: конструктор 3000 тенге, скидка 500 тенге. Цена со скидкой?"],"hand":"Сдать: ответы с признаками.","answers":[["","Не реклама."],["","Реклама — надпись и ссылка."],["","Реклама — промокод, много раз марка."],["","Есть спонсор — частично реклама."],["","2500 тенге."]]},{"n":"2","title":"Памятка «Как узнать рекламу у блогера»","lines":["Признак 1: ____","Признак 2: ____","Признак 3: ____","Что делать, если сомневаюсь: ____"],"hand":"Сдать: памятку команды.","answers":[]}],"practice":[{"type":"scene","title":"Блогер и шоколадка","minutes":7,"setting":"Блогер снимает видео и как будто случайно хвалит шоколадку.","roles":[{"name":"Блогер","task":"Снимаешь видео и хвалишь шоколадку."},{"name":"Зритель","task":"Смотришь и думаешь: реклама это или нет?"},{"name":"Детектив рекламы","task":"Ищешь признаки рекламы."}],"steps":["Блогер снимает видео.","Зритель смотрит.","Детектив называет признаки."],"freeze":["Стоп-кадр! Какие признаки рекламы нашёл детектив?"],"twist":"Поворот: блогер не написал, что это реклама. Честно ли это?","debrief":["Как узнать скрытую рекламу?"]},{"type":"scene","title":"Честный блогер","minutes":6,"setting":"Блогер говорит прямо: «Это реклама».","roles":[{"name":"Блогер","task":"Честно говоришь, что это реклама, и рассказываешь о товаре."},{"name":"Подписчик","task":"Решаешь, доверяешь ли ты блогеру."}],"steps":["Блогер говорит про рекламу.","Подписчик реагирует."],"freeze":["Стоп-кадр! Стал ли подписчик доверять меньше или больше?"],"twist":null,"debrief":["Почему честность важна для блогера?"]},{"type":"scene","title":"Реклама или нет?","minutes":5,"setting":"Ведущий описывает видео, класс решает: реклама или обычное видео.","roles":[{"name":"Ведущий","task":"Описываешь 3 видео."},{"name":"Класс","task":"Поднимаете руку, если реклама."}],"steps":["Описание.","Голосование.","Объяснение."],"freeze":["Стоп-кадр! Почему это реклама?"],"twist":null,"debrief":["Какие признаки рекламы мы знаем?"]}],"homework":"Посмотреть с родителями одно видео в интернете и проверить его по «светофору рекламы».","support":"Список слов-сигналов («реклама», «спонсор», «промокод», «ссылка») и подсказка-светофор на парте.","advanced":"Придумать, как блогеру честно сказать о рекламе одной фразой, и написать её.","photo":{"src":"lessons/img/03_22.jpg","author":"Waddas Magalhães","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему важно, чтобы рекламу помечали честно?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g03-l22.pptx","name":"22. Реклама в интернете и у блогеров (3 кл).pptx","mb":1.4}},{"id":"03_23","g":3,"l":23,"topic":"Коммерческая и социальная реклама","module":"Реклама","format":"Комбинированный","skills":["Критическое мышление","Креативность"],"goal":"К концу урока ученик сможет отличить коммерческую рекламу от социальной на 6 примерах и объяснить разницу по цели: продать товар или изменить поведение людей.","criteria":["Я называю цель коммерческой и цель социальной рекламы.","Я правильно сортирую примеры и объясняю.","Я придумываю идею социального плаката для школы."],"result":"Таблица «Коммерческая или социальная?» по 6 примерам и эскиз одного социального плаката для школы.","stages":[{"stage":"Разминка «Найди пару»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Реклама (advertising)","real":"Сообщение, которое что-то предлагает людям","shown":"Сообщение, которое что-то предлагает людям","truth":true,"first":"Р"},{"term":"Бизнес-реклама (коммерческая)","real":"Реклама, которая помогает продать товар или услугу","shown":"Слова, которые говорят, что сделать","truth":false,"first":"Б"},{"term":"Социальная реклама","real":"Реклама, которая призывает делать добрые и полезные дела, а не покупать","shown":"Реклама, которая призывает делать добрые и полезные дела, а не покупать","truth":true,"first":"С"},{"term":"Социальная ответственность бизнеса","real":"Когда компания помогает людям и природе, а не только зарабатывает","shown":"Реклама, которая помогает продать товар или услугу","truth":false,"first":"С"},{"term":"Социальное предпринимательство (social entrepreneurship)","real":"Бизнес, который решает важную проблему общества","shown":"Бизнес, который решает важную проблему общества","truth":true,"first":"С"},{"term":"Призыв","real":"Слова, которые говорят, что сделать","shown":"Когда компания помогает людям и природе, а не только зарабатывает","truth":false,"first":"П"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Реклама (advertising)","def":"Сообщение, которое что-то предлагает людям"},{"term":"Бизнес-реклама (коммерческая)","def":"Реклама, которая помогает продать товар или услугу"},{"term":"Социальная реклама","def":"Реклама, которая призывает делать добрые и полезные дела, а не покупать"},{"term":"Социальная ответственность бизнеса","def":"Когда компания помогает людям и природе, а не только зарабатывает"},{"term":"Социальное предпринимательство (social entrepreneurship)","def":"Бизнес, который решает важную проблему общества"},{"term":"Призыв","def":"Слова, которые говорят, что сделать"}],"english":"advertising — реклама; social entrepreneurship — социальное предпринимательство","concepts":{"head":"Понятия","items":["Коммерческая (бизнес-) реклама — чтобы купили товар: «Новый сок — попробуй!».","Социальная реклама — чтобы люди поступали хорошо: «Береги воду», «Пристегнись».","Социальная ответственность бизнеса — компания помогает обществу.","Социальное предпринимательство (social entrepreneurship) — бизнес, созданный, чтобы решить проблему."]},"steps":{"head":"Как отличить, по шагам","items":["Что предлагает реклама — купить или сделать доброе дело?","Есть ли цена и название товара?","Кто получит пользу — компания или все люди?","Какой призыв? Если цель — поменять поведение для общего блага, это социальная реклама"]},"scheme":"Две колонки: «Коммерческая: цель — продать, есть товар и цена, пользу получает компания» и «Социальная: цель — доброе дело, нет цены, пользу получают все». Посередине стрелка «Социальная ответственность бизнеса».","examples":[{"lab":"Казахстан","text":"2020 год в Казахстане был объявлен Годом волонтёра, и социальная реклама призывала людей помогать пожилым и нуждающимся."},{"lab":"Пример коммерческой","text":"Плакат кафе «Плов за 900 тенге». Социальное предпринимательство: мастерская, где люди с особыми потребностями шьют сумки; продали 2 сумки по 500 тенге: 500 + 500 = 1000 тенге, и эти деньги идут на зарплату мастерам и развитие мастерской."},{"lab":"Мир","text":"В США с 1944 года медведь Смоки в социальной рекламе учит людей беречь лес от пожаров."}],"mistake":{"myth":"«Если на плакате есть логотип фирмы — значит, коммерческая»","fix":"Посмотреть на цель и призыв; компания может поддерживать социальную рекламу."},"check":[{"q":"«Выключай свет, уходя» — какая реклама?","a":"Социальная"},{"q":"«Новые кроссовки — 900 тенге» — какая?","a":"Коммерческая"},{"q":"Может ли компания делать социальную рекламу?","a":"Да, это её социальная ответственность"}],"kz":{"text":"Год волонтёра в Казахстане (2020). В этот год по всей стране показывали социальную рекламу о волонтёрах, которые помогают пожилым людям, животным и природе.","link":"это реклама не товара, а доброго поведения."},"world":{"text":"В США с 1944 года социальная реклама с медведем Смоки учит беречь лес: «Только ты можешь предотвратить лесные пожары». Это связано с ЦУР ООН № 15 «Сохранение экосистем суши».","link":""},"fact":"Медведь Смоки стал символом кампании Службы леса США в 1944 году, и это одна из самых долгих социальных рекламных кампаний в истории.","cards":[{"n":"1","title":"Коммерческая или социальная?","lines":["1) «Новый сок “Алма” — 300 тенге!» 2) «Выключай воду, когда чистишь зубы». 3) «Пристегнись — береги себя». 4) «Кружок робототехники — запишись!» 5) «Покорми птиц зимой». 6) «Магазин спорттоваров дарит школе 10 мячей. Занимайся спортом!»","Ответы для тренера: коммерческая — 1, 4; социальная — 2, 3, 5; пример 6 — социальная ответственность бизнеса (компания помогает и напоминает о себе)."],"hand":"Сдать: таблицу с объяснениями.","answers":[]},{"n":"2","title":"Эскиз социального плаката для школы","lines":["Проблема: мусор во дворе / шум в коридоре / не выключают свет / новичкам одиноко.","Призыв (до 5 слов): ____","Картинка: ____","Кто получит пользу: ____"],"hand":"Сдать: эскиз.","answers":[]}],"practice":[{"type":"scene","title":"Два плаката","minutes":7,"setting":"Два художника рисуют плакаты: один продаёт мороженое, другой просит беречь воду.","roles":[{"name":"Художник коммерческой рекламы","task":"Рисуешь плакат мороженого."},{"name":"Художник социальной рекламы","task":"Рисуешь плакат «Береги воду»."},{"name":"Зритель","task":"Говоришь, какой плакат что просит сделать."}],"steps":["Художники показывают плакаты.","Зритель объясняет цель каждого."],"freeze":["Стоп-кадр! Чем отличаются цели плакатов?"],"twist":"Поворот: на плакате «Береги воду» нарисована бутылка известной воды. Какая это теперь реклама?","debrief":["Чем коммерческая реклама отличается от социальной?"]},{"type":"scene","title":"Сортировка","minutes":6,"setting":"Ведущий показывает примеры, команды сортируют их на две стороны.","roles":[{"name":"Ведущий","task":"Называешь пример рекламы."},{"name":"Команда «Коммерческая»","task":"Забираешь свои примеры."},{"name":"Команда «Социальная»","task":"Забираешь свои примеры."}],"steps":["Пример.","Сортировка.","Проверка."],"freeze":["Стоп-кадр! Почему этот пример здесь?"],"twist":null,"debrief":["Как отличить рекламу по цели?"]},{"type":"scene","title":"Плакат для школы","minutes":5,"setting":"Команда придумывает идею социального плаката для школы.","roles":[{"name":"Автор идеи","task":"Предлагаешь, к чему призываем."},{"name":"Команда","task":"Придумываете призыв."}],"steps":["Идея.","Призыв.","Показ."],"freeze":["Стоп-кадр! К чему зовёт плакат?"],"twist":null,"debrief":["Зачем нужна социальная реклама?"]}],"homework":"Найти с родителями одну социальную рекламу (на улице, по телевизору) и записать её призыв.","support":"Карточки-примеры с картинками и вопрос-подсказка «Здесь что-то продают?».","advanced":"Придумать, как кафе или магазин может сделать социальную рекламу и показать свою социальную ответственность.","photo":{"src":"lessons/img/03_23.jpg","author":"ray sangga kusuma","q":["Что вы видите на фото? Как это связано с нашей темой?","Какую проблему нашего края могла бы решить социальная реклама?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g03-l23.pptx","name":"23. Коммерческая и социальная реклама (3 кл).pptx","mb":1.4}},{"id":"03_24","g":3,"l":24,"topic":"Ярмарка: зазывалка и мини-ролик","module":"Реклама","format":"Симуляция, ярмарка","skills":["Командная работа","Презентация","Работа с клиентом"],"goal":"К концу урока ученик сможет подготовить и выполнить свою роль на ярмарке — зазывала, актёр мини-ролика, продавец или кассир — и посчитать выручку команды в пределах 1000 тенге.","criteria":["Я выполняю свою роль на ярмарке.","Наша зазывалка и мини-ролик короткие, понятные и честные.","Я правильно считаю выручку и сравниваю её с целью команды."],"result":"Зазывалка (2–4 строки) и мини-ролик-сценка на 30 секунд о товаре команды, показанные на ярмарке; итог продаж в тенге.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Подготовка","min":6},{"stage":"Ярмарка","min":18},{"stage":"Подсчёт","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Ярмарка (fair)","real":"Праздничный рынок на один день","shown":"Праздничный рынок на один день","truth":true,"first":"Я"},{"term":"Роль (role)","real":"Задача человека в команде: зазывала, актёр, продавец, кассир","shown":"Сколько команда хочет продать и заработать","truth":false,"first":"Р"},{"term":"Зазывалка","real":"Короткая весёлая фраза или стишок, которым зовут покупателей","shown":"Короткая весёлая фраза или стишок, которым зовут покупателей","truth":true,"first":"З"},{"term":"Мини-ролик","real":"Короткая сценка-реклама на 15–30 секунд","shown":"Задача человека в команде: зазывала, актёр, продавец, кассир","truth":false,"first":"М"},{"term":"Выручка","real":"Все деньги за проданные товары","shown":"Все деньги за проданные товары","truth":true,"first":"В"},{"term":"Цель продаж","real":"Сколько команда хочет продать и заработать","shown":"Короткая сценка-реклама на 15–30 секунд","truth":false,"first":"Ц"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Ярмарка (fair)","def":"Праздничный рынок на один день"},{"term":"Роль (role)","def":"Задача человека в команде: зазывала, актёр, продавец, кассир"},{"term":"Зазывалка","def":"Короткая весёлая фраза или стишок, которым зовут покупателей"},{"term":"Мини-ролик","def":"Короткая сценка-реклама на 15–30 секунд"},{"term":"Выручка","def":"Все деньги за проданные товары"},{"term":"Цель продаж","def":"Сколько команда хочет продать и заработать"}],"english":"fair — ярмарка; role — роль","concepts":{"head":"Понятия","items":["Зазывалка — короткий стишок или кричалка, которой торговцы на базарах зовут покупателей.","Мини-ролик — живая сценка-реклама.","Роль (role) — задача каждого.","Выручка — деньги за продажи.","Цель продаж — план команды."]},"steps":{"head":"Как подготовиться, по шагам","items":["Распределить роли: зазывала, 2 актёра, продавец, кассир","Придумать зазывалку из 2–4 строк с названием товара","Сделать мини-ролик по схеме «герой — проблема — решение» на 30 секунд","Поставить цель: например, продать 8 товаров по 100 тенге — 800 тенге","На ярмарке зазывать вежливо, не мешая соседям","Считать выручку"]},"scheme":"Круг ролей: зазывала → актёры (мини-ролик) → продавец → кассир. Справа табличка: «Цель: 8 × 100 = 800. Факт: ___».","examples":[{"lab":"Казахстан","text":"На базарах Алматы и Шымкента продавцы громко и весело зазывают: «Апорт сладкий, как мёд!» Наш"},{"lab":"Пример","text":"«Брелок-асык, брелок-асык — с ним удача будет с вами!» Продали 7 брелоков по 120 тенге: 7 × 120 = 840 тенге. Цель была 800 — выполнили."},{"lab":"Мир","text":"На старинных ярмарках Европы торговцы тоже кричали короткие стишки о товаре, чтобы их услышали в толпе."}],"mistake":{"myth":"Зазывала кричит так громко, что мешает другим командам, или обещает неправду («Самый лучший в мире!»)","fix":"Правило «громко, но вежливо, и только правду»."},"check":[{"q":"Чем зазывалка отличается от листовки?","a":"Она звучит вслух и сразу привлекает внимание"},{"q":"Сколько длится мини-ролик?","a":"15–30 секунд"},{"q":"6 товаров по 150 тенге — какая выручка?","a":"900 тенге"}],"kz":{"text":"Зелёный базар в Алматы — известный рынок, где продавцы громко и весело зазывают покупателей попробовать фрукты, сухофрукты и сладости.","link":"живое слово и угощение — старейшая реклама."},"world":{"text":"На старинных ярмарках Европы и на восточных базарах торговцы привлекали покупателей криками и песенками, а сегодня то же делают короткие видеоролики в интернете.","link":""},"fact":"В Средние века в европейских городах были «городские глашатаи», которые за плату объявляли на площадях новости и рекламу торговцев.","cards":[{"n":"1","title":"Роли (role) команды","lines":["Зазывала — ___ Актёры мини-ролика — ___, ___ Продавец — ___ Кассир — ___","Зазывалка (2–4 строки, с названием товара): ____","Пример: «Брелок-асык, брелок-асык — с ним удача будет с вами!»"],"hand":"Сдать: список ролей и зазывалку.","answers":[]},{"n":"2","title":"Мини-ролик (30 секунд)","lines":["Герой: ___ Проблема: ___ Решение (наш товар): ___ Слоган и цена: ___"],"hand":"Сдать: план сценки.","answers":[]},{"n":"3","title":"Итоги ярмарки","lines":["Цель: ___ товаров × ___ тенге = ___ тенге.","Продано: ___ товаров. Выручка: ___ тенге.","Цель выполнена? Да / Нет. На сколько больше или меньше? ___","Задача: продали 7 брелоков по 120 тенге. Выручка?","Что сработало лучше: зазывалка или ролик? ___"],"hand":"Сдать: карточку.","answers":[["","840 тенге."]]}],"practice":[{"type":"scene","title":"Зазывала","minutes":7,"setting":"Ярмарка! Зазывала громко приглашает покупателей к прилавку.","roles":[{"name":"Зазывала","task":"Короткая весёлая фраза, чтобы позвать покупателей."},{"name":"Покупатели","task":"Идёте мимо и решаете, подойти ли."},{"name":"Продавец","task":"Встречаешь тех, кто подошёл."}],"steps":["Зазывала зовёт.","Покупатели подходят или нет.","Продавец встречает."],"freeze":["Стоп-кадр! Какая фраза зазывалы сработала?"],"twist":"Поворот: соседний зазывала кричит громче. Как выделиться без крика?","debrief":["Какой должна быть зазывалка?"]},{"type":"scene","title":"Мини-ролик на ярмарке","minutes":6,"setting":"Команда показывает 15-секундный ролик о товаре.","roles":[{"name":"Актёр","task":"Показываешь товар в деле."},{"name":"Диктор","task":"Говоришь слоган и цену."},{"name":"Покупатель","task":"Решаешь, купить ли."}],"steps":["Ролик.","Решение покупателя."],"freeze":["Стоп-кадр! Был ли ролик честным?"],"twist":null,"debrief":["Что важно в коротком ролике?"]},{"type":"scene","title":"Честная зазывалка","minutes":5,"setting":"Зазывала придумал громкую фразу: «Самые лучшие кексы в мире!» А кексы — обычные.","roles":[{"name":"Зазывала","task":"Говоришь преувеличенную фразу, потом честную."},{"name":"Покупатель","task":"Пробуешь кекс и говоришь, обманули тебя или нет."},{"name":"Режиссёр","task":"Предлагаешь короткую и честную зазывалку."}],"steps":["Нечестная зазывалка.","Покупатель разочарован.","Новая честная зазывалка до 6 слов."],"freeze":["Стоп-кадр! Какая зазывалка честная и понятная?"],"twist":null,"debrief":["Почему зазывалка должна быть короткой и честной?"]}],"homework":"Рассказать зазывалку команды родителям и спросить, захотелось ли им купить товар; записать их ответ.","support":"Банк готовых зазывалок для переделки и роль кассира с таблицей подсчёта.","advanced":"Быть «режиссёром» мини-ролика: следить за временем и предложить, как уложить сценку в 15 секунд.","photo":{"src":"lessons/img/03_24.jpg","author":"Jonathan Borba","q":["Что вы видите на фото? Как это связано с нашей темой?","Что работает лучше на живой ярмарке — листовка, зазывалка или сценка, и почему?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g03-l24.pptx","name":"24. Ярмарка — зазывалка и мини-ролик (3 кл).pptx","mb":1.8}},{"id":"03_25","g":3,"l":25,"topic":"Коммерческая и социальная реклама: практикум","module":"Реклама","format":"Проектная мастерская","skills":["Креативность","Командная работа","Финансовое мышление"],"goal":"К концу урока команда сможет сделать социальный плакат для школы с одной проблемой, коротким призывом и картинкой и уложить расходы на плакаты в бюджет 1000 тенге.","criteria":["На нашем плакате понятна проблема и есть призыв до 6 слов.","Плакат не продаёт товар, а зовёт к доброму делу.","Я правильно считаю, сколько копий поместится в бюджет."],"result":"Социальный плакат команды формата А3 для школы и расчёт: сколько копий плаката можно напечатать на 1000 тенге.","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Социальная реклама","real":"Реклама, которая призывает к доброму и полезному поведению","shown":"Реклама, которая призывает к доброму и полезному поведению","truth":true,"first":"С"},{"term":"Бизнес-реклама","real":"Реклама, которая помогает продать товар","shown":"Когда мы делаем сами то, что узнали","truth":false,"first":"Б"},{"term":"Социальная ответственность бизнеса","real":"Когда компания заботится о людях и природе","shown":"Когда компания заботится о людях и природе","truth":true,"first":"С"},{"term":"Социальное предпринимательство (social entrepreneurship)","real":"Бизнес, который помогает решить проблему общества","shown":"Реклама, которая помогает продать товар","truth":false,"first":"С"},{"term":"Призыв","real":"Короткие слова о том, что нужно сделать","shown":"Короткие слова о том, что нужно сделать","truth":true,"first":"П"},{"term":"Практика (practice)","real":"Когда мы делаем сами то, что узнали","shown":"Бизнес, который помогает решить проблему общества","truth":false,"first":"П"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Социальная реклама","def":"Реклама, которая призывает к доброму и полезному поведению"},{"term":"Бизнес-реклама","def":"Реклама, которая помогает продать товар"},{"term":"Социальная ответственность бизнеса","def":"Когда компания заботится о людях и природе"},{"term":"Социальное предпринимательство (social entrepreneurship)","def":"Бизнес, который помогает решить проблему общества"},{"term":"Призыв","def":"Короткие слова о том, что нужно сделать"},{"term":"Практика (practice)","def":"Когда мы делаем сами то, что узнали"}],"english":"advertising — реклама; social entrepreneurship — социальное предпринимательство","concepts":{"head":"Понятия","items":["Социальная реклама (advertising) зовёт поступать хорошо, а не покупать.","Призыв — что сделать.","Социальная ответственность бизнеса — компания помогает обществу.","Социальное предпринимательство — бизнес, который решает проблему."]},"steps":{"head":"Как сделать социальный плакат, по шагам","items":["Выбрать одну проблему школы","Понять, кто её решает (ученики, родители, учителя)","Придумать призыв до 6 слов, без ругани: «Сортируй мусор — береги планету!»","Одна крупная картинка","Проверить: понятно ли за 3 секунды?","Посчитать расходы на копии"]},"scheme":"Макет А3: сверху призыв крупно, в центре картинка, внизу маленькая строка «Кто мы» (3 «Б» класс). Сбоку чек-лист: «Одна проблема», «Призыв до 6 слов», «Нет цены и товара», «Понятно за 3 секунды».","examples":[{"lab":"Казахстан","text":"В школах и городах Казахстана проходят субботники и акции по сбору макулатуры, их приглашают плакатами. Наш"},{"lab":"Расчёт","text":"Копия А3 стоит 80 тенге, бюджет 1000 тенге. 80 × 12 = 960 тенге — можно 12 копий, останется 40 тенге."},{"lab":"Мир","text":"Всемирная акция «Час Земли», когда люди выключают свет на час, тоже начиналась с социальной рекламы."}],"mistake":{"myth":"На плакате ругают («Не будь грязнулей!») или пишут сразу 5 проблем","fix":"Переделать в доброжелательный призыв и оставить одну проблему."},"check":[{"q":"Чем социальный плакат отличается от бизнес-рекламы?","a":"Он ничего не продаёт, а зовёт к доброму делу"},{"q":"Почему призыв должен быть коротким?","a":"Чтобы прочитали на ходу"},{"q":"Копия 80 тенге, сколько копий на 1000 тенге?","a":"12, останется 40"}],"kz":{"text":"Акции по сбору макулатуры и субботники в школах Казахстана. Ученики собирают бумагу, её сдают на переработку, а вырученные деньги часто идут на нужды класса или благотворительность.","link":"социальный плакат приглашает к участию."},"world":{"text":"Всемирная акция «Час Земли», которую проводит фонд WWF, призывает людей в разных странах выключить свет на один час, чтобы напомнить о бережном отношении к природе. Её поддерживают социальной рекламой во многих городах мира.","link":""},"fact":"Акция «Час Земли» впервые прошла в Сиднее (Австралия) в 2007 году, а сейчас в ней участвуют люди более чем в 190 странах и территориях.","cards":[{"n":"1","title":"Наш социальный плакат","lines":["Проблема школы (выберите одну): мусор во дворе; шум в коридоре; не выключают свет; одиноко новичкам; мало читают.","Призыв (до 6 слов, доброжелательно): ____","Картинка: ____","Кто должен увидеть: ____","Чек-лист: одна проблема / призыв до 6 слов / нет цены и товара / понятно за 3 секунды."],"hand":"Сдать: плакат А3.","answers":[]},{"n":"2","title":"Бюджет на копии","lines":["Бюджет — 1000 тенге. Копия А3 — 80 тенге.","1) Сколько копий можно сделать?","2) Сколько тенге останется?","3) Цветная копия — 100 тенге. Сколько цветных копий на 1000 тенге?"],"hand":"Сдать: решения.","answers":[["1","12, потому что 80 × 12 = 960."],["2","40."],["3","10."]]}],"practice":[{"type":"scene","title":"Плакат добрых дел","minutes":7,"setting":"Команда делает социальный плакат: проблема и призыв до 6 слов.","roles":[{"name":"Исследователь","task":"Называешь проблему в школе."},{"name":"Художник","task":"Рисуешь плакат."},{"name":"Писатель","task":"Придумываешь призыв до 6 слов."}],"steps":["Проблема.","Рисунок.","Призыв."],"freeze":["Стоп-кадр! Призыв короче 6 слов?"],"twist":"Поворот: на плакат хватает денег только на 3 копии. Где их повесить?","debrief":["Чем социальный плакат отличается от рекламы товара?"]},{"type":"scene","title":"Зовёт, а не продаёт","minutes":6,"setting":"На социальном плакате «Береги воду» художник нарисовал свою бутылку сока с ценой.","roles":[{"name":"Художник","task":"Защищаешь свой плакат."},{"name":"Критик","task":"Объясняешь, почему это уже не социальная реклама."},{"name":"Редактор","task":"Предлагаешь, что убрать и что оставить."}],"steps":["Художник показывает плакат.","Критик находит ошибку.","Редактор исправляет."],"freeze":["Стоп-кадр! Что продаёт этот плакат, а к чему зовёт?"],"twist":null,"debrief":["Чем социальный плакат отличается от рекламы товара?"]},{"type":"scene","title":"Проверка плаката","minutes":5,"setting":"Зрители смотрят на плакат 5 секунд и пересказывают призыв.","roles":[{"name":"Показчик","task":"Показываешь плакат 5 секунд."},{"name":"Зрители","task":"Пересказываете, к чему зовёт плакат."}],"steps":["Показ.","Пересказ."],"freeze":["Стоп-кадр! Поняли ли призыв?"],"twist":null,"debrief":["Почему плакат должен быть понятным за секунды?"]}],"homework":"Рассказать родителям о проблеме, которую выбрала команда, и спросить, какой призыв они бы добавили.","support":"Банк призывов и картинок на выбор; расчёт копий с таблицей «80, 160, 240…».","advanced":"Сделать вариант плаката на казахском языке или придумать вторую версию призыва для первоклассников.","photo":{"src":"lessons/img/03_25.jpg","author":"ray sangga kusuma","q":["Что вы видите на фото? Как это связано с нашей темой?","Какую акцию мог бы поддержать наш плакат?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g03-l25.pptx","name":"25. Коммерческая и социальная реклама — практикум (3 кл).pptx","mb":1.5}},{"id":"03_26","g":3,"l":26,"topic":"Моя идея для родного края: реклама и цена","module":"Реклама","format":"Комбинированный","skills":["Финансовое мышление","Креативность","Инициативность"],"goal":"К концу урока ученик сможет сделать рекламу своей идеи для родного края (заголовок, картинка, призыв) и назвать цену товара, рассчитанную из стоимости и наценки в пределах 1000 тенге.","criteria":["Моя реклама показывает, что за товар и для кого.","Я называю цену и объясняю, из чего она сложилась.","Я добавляю в рекламу честный призыв."],"result":"Рекламный мини-плакат своей идеи для родного края с ценой и расчётом цены (материалы + работа + реклама на 1 штуку).","stages":[{"stage":"Разминка «Найди пару»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Реклама (advertising)","real":"Сообщение, которое приглашает купить товар","shown":"Сообщение, которое приглашает купить товар","truth":true,"first":"Р"},{"term":"Цена (price)","real":"Сколько тенге платит покупатель","shown":"Люди, для которых сделан товар","truth":false,"first":"Ц"},{"term":"Стоимость","real":"Сколько потратили, чтобы сделать товар","shown":"Сколько потратили, чтобы сделать товар","truth":true,"first":"С"},{"term":"Расходы на рекламу","real":"Деньги на листовки, плакаты или ролики","shown":"Сколько тенге платит покупатель","truth":false,"first":"Р"},{"term":"Преимущество","real":"Чем товар лучше или интереснее других","shown":"Чем товар лучше или интереснее других","truth":true,"first":"П"},{"term":"Целевая аудитория","real":"Люди, для которых сделан товар","shown":"Деньги на листовки, плакаты или ролики","truth":false,"first":"Ц"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Реклама (advertising)","def":"Сообщение, которое приглашает купить товар"},{"term":"Цена (price)","def":"Сколько тенге платит покупатель"},{"term":"Стоимость","def":"Сколько потратили, чтобы сделать товар"},{"term":"Расходы на рекламу","def":"Деньги на листовки, плакаты или ролики"},{"term":"Преимущество","def":"Чем товар лучше или интереснее других"},{"term":"Целевая аудитория","def":"Люди, для которых сделан товар"}],"english":"price — цена; advertising — реклама","concepts":{"head":"Понятия","items":["Цена (price) — сколько платит покупатель.","Стоимость — сколько потратили.","В цену входят материалы, работа и часть расходов на рекламу (advertising).","Преимущество — чем товар особенный."]},"steps":{"head":"Как сделать рекламу и цену, по шагам","items":["Вспомнить свою идею для родного края (товар, покупатель, связь с краем)","Посчитать стоимость: материалы + работа","Добавить часть расходов на рекламу на 1 товар","Добавить прибыль — получить цену","Сделать рекламу: заголовок, картинка, преимущество, цена, призыв","Проверить, понятно ли целевой аудитории"]},"scheme":"Слева «лесенка цены»: материалы → работа → реклама на 1 шт. → прибыль → цена. Справа макет рекламы: заголовок, картинка, преимущество, цена, призыв.","examples":[{"lab":"Казахстан","text":"Идея «Магнит “Чарынский каньон”» для туристов. Материалы 150 тенге, работа 200 тенге. Листовки на 10 магнитов стоят 300 тенге, значит, на 1 магнит — 30 тенге. Прибыль 120 тенге. Цена: 150 + 200 + 30 + 120 = 500 тенге. Реклама: «Увези каньон с собой! Магнит ручной работы — 500 тенге. Спрашивай у входа в парк»."},{"lab":"Мир","text":"В Италии сувениры с видами городов продают туристам рядом с достопримечательностями — реклама и место продажи вместе."}],"mistake":{"myth":"Цена в рекламе не совпадает с расчётом или её нет вовсе","fix":"Сначала расчёт, потом реклама, и проверить, что цифры одинаковые."},"check":[{"q":"Почему расходы на рекламу входят в цену?","a":"Их тоже нужно вернуть"},{"q":"Листовки 300 тенге на 10 товаров — сколько на 1?","a":"30 тенге"},{"q":"Что обязательно в рекламе?","a":"Что за товар, цена, призыв"}],"kz":{"text":"Чарынский каньон — природный парк в Алматинской области, куда приезжает много туристов. Рядом с такими местами продают сувениры, предлагают экскурсии и еду.","link":"идея товара связана с краем, а реклама и цена помогают туристам его выбрать."},"world":{"text":"В Италии и Франции сувениры с видами городов продают прямо рядом с достопримечательностями, и туристы увозят их по всему миру — так товар рекламирует и сам город.","link":""},"fact":"Чарынский каньон часто сравнивают с Большим каньоном в США; его длина около 150 километров, а «Долина замков» — самая известная часть каньона.","cards":[{"n":"1","title":"Цена моей идеи (price)","lines":["Товар: ____ Покупатель: ____","Материалы: ___ тенге. Работа: ___ тенге.","Реклама: листовки ___ тенге ÷ ___ товаров = ___ тенге на 1 товар.","Прибыль: ___ тенге.","Цена = ___ + ___ + ___ + ___ = ___ тенге (не больше 1000).","Пример: 150 + 200 + 30 + 120 = 500 тенге."],"hand":"Сдать: расчёт.","answers":[]},{"n":"2","title":"Реклама моей идеи","lines":["Заголовок (до 5 слов): ____","Картинка: ____","Преимущество: ____","Цена: ____ тенге (как в расчёте!).","Призыв и где купить: ____"],"hand":"Сдать: мини-плакат.","answers":[]}],"practice":[{"type":"scene","title":"Реклама моей идеи","minutes":7,"setting":"Автор рекламирует свою идею для родного края.","roles":[{"name":"Автор","task":"Показываешь, что за товар и для кого."},{"name":"Житель","task":"Спрашиваешь цену."},{"name":"Проверяющий","task":"Проверяешь, честна ли реклама."}],"steps":["Реклама.","Вопрос о цене.","Проверка."],"freeze":["Стоп-кадр! Понятно ли, для кого товар?"],"twist":"Поворот: житель говорит: «Дорого». Как объяснить цену?","debrief":["Что должно быть в рекламе идеи?"]},{"type":"scene","title":"Из чего цена","minutes":6,"setting":"Автор объясняет, из чего сложилась цена.","roles":[{"name":"Автор","task":"Называешь части цены."},{"name":"Счетовод","task":"Складываешь."}],"steps":["Части цены.","Сложение."],"freeze":["Стоп-кадр! Сходится ли сумма?"],"twist":null,"debrief":["Как объяснить цену покупателю?"]},{"type":"scene","title":"Честный призыв","minutes":5,"setting":"Нужно добавить в рекламу честный призыв.","roles":[{"name":"Писатель","task":"Предлагаешь призыв."},{"name":"Класс","task":"Проверяете, честный ли он."}],"steps":["Призыв.","Проверка."],"freeze":["Стоп-кадр! Нет ли в призыве обмана?"],"twist":null,"debrief":["Что такое честный призыв?"]}],"homework":"Показать рекламу своей идеи родителям и спросить, купили бы они товар за эту цену; если нет — почему.","support":"Таблица расчёта с готовыми строками и числами, банк заголовков.","advanced":"Посчитать, как изменится цена, если листовки напечатать на 20 товаров, а не на 10 (реклама на 1 шт. станет 15 тенге).","photo":{"src":"lessons/img/03_26.jpg","author":"Jess Bailey","q":["Что вы видите на фото? Как это связано с нашей темой?","Как ваш товар мог бы рассказать гостям из других стран о родном крае?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g03-l26.pptx","name":"26. Моя идея для родного края — реклама и цена (3 кл).pptx","mb":1.4}},{"id":"03_27","g":3,"l":27,"topic":"После ярмарки: что запомнили покупатели","module":"Реклама","format":"Симуляция, ярмарка","skills":["Критическое мышление","Работа с клиентом","Финансовое мышление"],"goal":"К концу урока ученик сможет по данным мини-опроса покупателей и цифрам продаж назвать, что покупатели запомнили из рекламы команды, и предложить одно изменение рекламы.","criteria":["Я провожу опрос и записываю ответы покупателей.","Я считаю, сколько человек запомнили название, слоган и цену.","Я делаю вывод и предлагаю изменение рекламы."],"result":"Результаты мини-опроса «Что вы запомнили?» (10 ответов) в таблице, выручка ярмарки и одно изменение рекламы, проверенное на повторной мини-ярмарке.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Подготовка","min":6},{"stage":"Ярмарка","min":18},{"stage":"Подсчёт","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Ярмарка (fair)","real":"Праздничный рынок на один день","shown":"Праздничный рынок на один день","truth":true,"first":"Я"},{"term":"Покупатель (customer)","real":"Человек, который платит и получает товар","shown":"Что мы поняли по цифрам и ответам","truth":false,"first":"П"},{"term":"Опрос","real":"Когда задают одинаковые вопросы многим людям и записывают ответы","shown":"Когда задают одинаковые вопросы многим людям и записывают ответы","truth":true,"first":"О"},{"term":"Запоминаемость","real":"Сколько людей помнят рекламу через некоторое время","shown":"Человек, который платит и получает товар","truth":false,"first":"З"},{"term":"Выручка","real":"Все деньги за проданные товары","shown":"Все деньги за проданные товары","truth":true,"first":"В"},{"term":"Вывод","real":"Что мы поняли по цифрам и ответам","shown":"Сколько людей помнят рекламу через некоторое время","truth":false,"first":"В"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Ярмарка (fair)","def":"Праздничный рынок на один день"},{"term":"Покупатель (customer)","def":"Человек, который платит и получает товар"},{"term":"Опрос","def":"Когда задают одинаковые вопросы многим людям и записывают ответы"},{"term":"Запоминаемость","def":"Сколько людей помнят рекламу через некоторое время"},{"term":"Выручка","def":"Все деньги за проданные товары"},{"term":"Вывод","def":"Что мы поняли по цифрам и ответам"}],"english":"fair — ярмарка; customer — покупатель","concepts":{"head":"Понятия","items":["Опрос — одинаковые вопросы многим покупателям (customers).","Запоминаемость — сколько человек из опрошенных помнят рекламу.","Выручка — деньги за продажи.","Вывод — что поняли."]},"steps":{"head":"Как разобрать итоги, по шагам","items":["Опросить 10 покупателей: «Какое название запомнили? Какой слоган? Какую цену?»","Посчитать, сколько из 10 запомнили каждое","Посчитать выручку","Сравнить команды: где запомнили больше и продали больше?","Найти, что плохо запоминается, и изменить","Проверить изменение на мини-ярмарке"]},"scheme":"Столбчатая диаграмма для каждой команды: три столбика «Название», «Слоган», «Цена» высотой от 0 до 10. Рядом — выручка в тенге.","examples":[{"lab":"Казахстан","text":"Команда «Асык» опросила 10 покупателей: название запомнили 8 из 10, слоган — 3 из 10, цену — 5 из 10. Выручка — 840 тенге. Вывод: слоган длинный; новый слоган «Асык — к удаче!» на мини-ярмарке запомнили 7 из 10."},{"lab":"Мир","text":"Компании во многих странах проводят опросы после рекламы, чтобы узнать, запомнили ли люди название товара."}],"mistake":{"myth":"Опрашивают только друзей своей команды, которые и так всё знают","fix":"Спрашивать покупателей из других команд, у всех одинаковые вопросы."},"check":[{"q":"Название запомнили 8 из 10, слоган — 3 из 10. Что хуже запомнилось?","a":"Слоган"},{"q":"Зачем опрос?","a":"Узнать, что люди запомнили, а не гадать"},{"q":"Выручка 840 и 690 тенге — на сколько больше у первой команды?","a":"На 150 тенге"}],"kz":{"text":"Kaspi.kz в Казахстане узнают по красному цвету и узнаваемому логотипу: многие люди сразу вспоминают компанию, увидев красную рекламу.","link":"запоминаемость — когда люди помнят название и знак."},"world":{"text":"Во многих странах после рекламных кампаний компании проводят опросы: помнят ли люди название и что о нём думают. Так они тратят деньги на ту рекламу, которая работает.","link":""},"fact":"Исследователь Герман Эббингауз в XIX веке показал, что большая часть новой информации забывается в первые часы, если её не повторять; поэтому рекламу показывают несколько раз.","cards":[{"n":"1","title":"Опрос покупателей (customers)","lines":["Покупатель № ___","1) Какое название товара вы запомнили? Верно / Неверно.","2) Какой слоган запомнили? Верно / Неверно.","3) Какую цену запомнили? Верно / Неверно.","Выручка прошлой ярмарки: ___ тенге."],"hand":"Сдать: 10 бланков.","answers":[]},{"n":"2","title":"Итоги","lines":["Из 10 покупателей запомнили: название ___, слоган ___, цену ___.","Нарисуйте 3 столбика (одна клетка = 1 человек).","После нового слогана из 5 опрошенных запомнили слоган: ___.","Задача: выручка команды «Асык» 840 тенге, команды «Дала» 690 тенге. Разница?","Вывод: ____"],"hand":"Сдать: диаграмму и вывод.","answers":[["","150 тенге."]]}],"practice":[{"type":"scene","title":"Опрос покупателей","minutes":7,"setting":"Команда проводит опрос: что запомнили покупатели?","roles":[{"name":"Интервьюер","task":"Задаёшь 3 вопроса: название, слоган, цена."},{"name":"Покупатель 1","task":"Помнишь всё."},{"name":"Покупатель 2","task":"Помнишь только цену."},{"name":"Записывающий","task":"Отмечаешь ответы."}],"steps":["Интервью.","Ответы.","Запись."],"freeze":["Стоп-кадр! Что запомнили лучше всего?"],"twist":"Поворот: никто не запомнил название. Что изменить в рекламе?","debrief":["Зачем спрашивать покупателей?"]},{"type":"scene","title":"Считаем ответы","minutes":6,"setting":"Команда считает, сколько человек что запомнили.","roles":[{"name":"Счетовод","task":"Считаешь галочки."},{"name":"Капитан","task":"Делаешь вывод."}],"steps":["Подсчёт.","Вывод."],"freeze":["Стоп-кадр! Какой вывод?"],"twist":null,"debrief":["Как цифры помогают улучшить рекламу?"]},{"type":"scene","title":"Новая версия рекламы","minutes":5,"setting":"По итогам опроса команда меняет рекламу.","roles":[{"name":"Рекламщик","task":"Предлагаешь изменение."},{"name":"Команда","task":"Соглашаетесь или спорите."}],"steps":["Изменение.","Обсуждение."],"freeze":["Стоп-кадр! Что изменили?"],"twist":null,"debrief":["Что мы улучшим?"]}],"homework":"Через день спросить у 3 родственников, какой слоган команды они запомнили, и принести результат.","support":"Готовый бланк опроса с галочками «да/нет» и диаграмма с готовыми делениями.","advanced":"Посчитать, сколько всего ответов «да» собрала команда по трём вопросам, и сравнить с другой командой.","photo":{"src":"lessons/img/03_27.jpg","author":"Towfiqu barbhuiya","q":["Что вы видите на фото? Как это связано с нашей темой?","Какую рекламу вы помните через неделю и почему?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g03-l27.pptx","name":"27. После ярмарки — что запомнили покупатели (3 кл).pptx","mb":1.4}},{"id":"03_28","g":3,"l":28,"topic":"Рекламный форум","module":"Реклама","format":"Комбинированный","skills":["Презентация","Командная работа","Креативность"],"goal":"К концу урока ученик сможет назвать 4 шага подготовки к защите рекламного проекта и 4 критерия оценки и применить их, подготовив план защиты своей рекламы.","criteria":["Я называю шаги подготовки к защите.","Я называю критерии оценки рекламы на форуме.","Я знаю свою часть защиты и могу её рассказать."],"result":"Черновик рекламы команды для любого товара (плакат или сценарий ролика) и план защиты на 2 минуты с распределением ролей.","stages":[{"stage":"Разминка «Угадай слово»","min":5},{"stage":"Актуализация","min":3},{"stage":"Изучение нового","min":10},{"stage":"Практическая работа","min":12},{"stage":"Презентация","min":6},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Реклама (advertising)","real":"Сообщение о товаре, которое приглашает его купить","shown":"Сообщение о товаре, которое приглашает его купить","truth":true,"first":"Р"},{"term":"Форум","real":"Встреча, где команды показывают свои проекты и обсуждают их","shown":"Дело, которое делает товары или услуги","truth":false,"first":"Ф"},{"term":"Защита проекта","real":"Выступление, где команда объясняет свою работу и отвечает на вопросы","shown":"Выступление, где команда объясняет свою работу и отвечает на вопросы","truth":true,"first":"З"},{"term":"Критерии оценки","real":"Правила, по которым жюри ставит баллы","shown":"Встреча, где команды показывают свои проекты и обсуждают их","truth":false,"first":"К"},{"term":"Целевая аудитория","real":"Люди, для которых сделан товар","shown":"Люди, для которых сделан товар","truth":true,"first":"Ц"},{"term":"Бизнес (business)","real":"Дело, которое делает товары или услуги","shown":"Правила, по которым жюри ставит баллы","truth":false,"first":"Б"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Реклама (advertising)","def":"Сообщение о товаре, которое приглашает его купить"},{"term":"Форум","def":"Встреча, где команды показывают свои проекты и обсуждают их"},{"term":"Защита проекта","def":"Выступление, где команда объясняет свою работу и отвечает на вопросы"},{"term":"Критерии оценки","def":"Правила, по которым жюри ставит баллы"},{"term":"Целевая аудитория","def":"Люди, для которых сделан товар"},{"term":"Бизнес (business)","def":"Дело, которое делает товары или услуги"}],"english":"advertising — реклама; business — бизнес","concepts":{"head":"Понятия","items":["Рекламный форум — встреча, где команды защищают рекламу (advertising).","Защита — рассказ и ответы на вопросы.","Критерии — по чему оценивают."]},"steps":{"head":"Как готовиться к защите, по шагам","items":["Проверь рекламу: есть ли заголовок, картинка, цена, призыв","Составь план на 2 минуты: товар и целевая аудитория → идея рекламы → почему она сработает → цена и расходы","Распредели части между участниками","Подготовь ответы на 3 вероятных вопроса","Отрепетируй с таймером.\nКритерии форума (по 0–3 балла): 1) Понятность — ясно за 3 секунды. 2) Целевая аудитория — реклама для нужных людей. 3) Честность — нет обмана. 4) Креативность — необычная идея. Максимум 12 баллов"]},"scheme":"Слева лестница подготовки из 5 шагов, справа табло критериев: «Понятность | ЦА | Честность | Креативность | Итого из 12».","examples":[{"lab":"Казахстан","text":"На школьных и городских конкурсах проектов в Казахстане ученики защищают работы перед жюри по критериям."},{"lab":"Пример расчёта","text":"Команда потратила на рекламу: ватман 150 тенге, краски 300 тенге, печать листовок 400 тенге — всего 850 тенге из бюджета 1000; осталось 150 тенге."},{"lab":"Мир","text":"На больших выставках компании за пару минут представляют рекламу и отвечают на вопросы журналистов."}],"mistake":{"myth":"Команда читает с листа и не смотрит на слушателей, или один говорит за всех","fix":"Карточки-подсказки с 3 словами вместо текста и обязательная часть у каждого."},"check":[{"q":"Сколько длится защита?","a":"2 минуты"},{"q":"Бюджет 1000, потратили 850 — остаток?","a":"150 тенге"}],"kz":{"text":"Республиканские конкурсы научных и творческих проектов школьников в Казахстане: ученики защищают проекты перед жюри и отвечают на вопросы.","link":"подготовка к защите и критерии оценки там такие же, как на нашем форуме."},"world":{"text":"Каждый год во французском городе Канны проходит международный фестиваль рекламы «Каннские львы», где команды со всего мира показывают свою рекламу, а жюри оценивает её по критериям.","link":""},"fact":"Международный фестиваль «Каннские львы» проводится с 1954 года и считается одним из главных мировых конкурсов рекламы.","cards":[{"n":"1","title":"Черновик рекламы","lines":["Товар: ____ Целевая аудитория: ____","Вид рекламы: плакат / листовка / сценарий ролика.","Заголовок или слоган: ____ Картинка: ____ Цена: ____ Призыв: ____","Бюджет 1000 тенге: ватман 150 + краски 300 + печать 400 = ?"],"hand":"Сдать: черновик.","answers":[["","850; остаток 150 тенге."]]},{"n":"2","title":"План защиты (2 минуты)","lines":["Часть 1. Товар и целевая аудитория — говорит ___","Часть 2. Идея рекламы — говорит ___","Часть 3. Почему сработает (по критериям) — говорит ___","Часть 4. Цена и расходы — говорит ___","Вопросы жюри, к которым готовимся: 1) ___ 2) ___ 3) ___","Критерии (0–3): понятность, ЦА, честность, креативность."],"hand":"Сдать: план.","answers":[]}],"practice":[{"type":"scene","title":"Подготовка к форуму","minutes":7,"setting":"Команда готовится защищать рекламу на рекламном форуме.","roles":[{"name":"Капитан","task":"Распределяешь роли."},{"name":"Рассказчик","task":"Готовишь речь."},{"name":"Показчик","task":"Готовишь плакат."},{"name":"Ответчик","task":"Готовишься к вопросам."}],"steps":["Распределение ролей.","Подготовка.","Мини-прогон."],"freeze":["Стоп-кадр! Какие шаги подготовки мы прошли?"],"twist":"Поворот: рассказчик заболел. Кто заменит?","debrief":["Какие шаги подготовки к защите?"]},{"type":"scene","title":"Критерии жюри","minutes":6,"setting":"Жюри объясняет, по каким критериям оценивает рекламу.","roles":[{"name":"Жюри","task":"Называешь критерии: понятность, для кого, честность, креативность."},{"name":"Участники","task":"Проверяете свою рекламу по критериям."}],"steps":["Критерии.","Самопроверка."],"freeze":["Стоп-кадр! По какому критерию слабее всего?"],"twist":null,"debrief":["Зачем знать критерии заранее?"]},{"type":"scene","title":"Пробная защита","minutes":5,"setting":"Одна команда показывает защиту, другая — жюри.","roles":[{"name":"Защищающиеся","task":"Рассказываете за 1 минуту."},{"name":"Жюри","task":"Оцениваете по критериям."}],"steps":["Защита.","Оценка."],"freeze":["Стоп-кадр! Уложились в минуту?"],"twist":null,"debrief":["Что улучшить к форуму?"]}],"homework":"Отрепетировать свою часть защиты дома перед родителями с таймером (30–40 секунд).","support":"Карточка-подсказка с началом фраз для своей части и 3 ключевыми словами.","advanced":"Подготовить ответы на 3 «трудных» вопроса жюри для всей команды.","photo":{"src":"lessons/img/03_28.jpg","author":"Product School","q":["Что вы видите на фото? Как это связано с нашей темой?","Какой критерий вы бы добавили для рекламы, которую смотрят дети?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g03-l28.pptx","name":"28. Рекламный форум (3 кл).pptx","mb":1.4}},{"id":"03_29","g":3,"l":29,"topic":"Рекламный форум: практикум","module":"Реклама","format":"Проектная мастерская","skills":["Презентация","Командная работа","Креативность"],"goal":"К концу урока команда сможет за 2 минуты защитить рекламный проект на форуме и ответить на 2 вопроса жюри, а ученик — выполнить свою часть защиты.","criteria":["Я выполняю свою часть защиты понятно и вовремя.","Наша реклама соответствует критериям: понятность, ЦА, честность, креативность.","Я отвечаю на вопрос жюри полным предложением."],"result":"Готовая реклама команды на ватмане А2 и её защита на рекламном форуме с оценкой жюри по 4 критериям (до 12 баллов).","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Постановка задачи","min":4},{"stage":"Работа в командах","min":20},{"stage":"Промежуточный показ","min":7},{"stage":"Рефлексия","min":5}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Реклама (advertising)","real":"Сообщение о товаре, которое приглашает его купить","shown":"Сообщение о товаре, которое приглашает его купить","truth":true,"first":"Р"},{"term":"Практика (practice)","real":"Когда мы делаем сами то, что изучили","shown":"Задание, где нужно придумать что-то своё","truth":false,"first":"П"},{"term":"Форум","real":"Встреча, где команды показывают проекты","shown":"Встреча, где команды показывают проекты","truth":true,"first":"Ф"},{"term":"Защита проекта","real":"Выступление с ответами на вопросы","shown":"Когда мы делаем сами то, что изучили","truth":false,"first":"З"},{"term":"Жюри","real":"Люди, которые оценивают выступления","shown":"Люди, которые оценивают выступления","truth":true,"first":"Ж"},{"term":"Творческое задание","real":"Задание, где нужно придумать что-то своё","shown":"Выступление с ответами на вопросы","truth":false,"first":"Т"}],"perm":[1,0,5,4,3,2]},"glossary":[{"term":"Реклама (advertising)","def":"Сообщение о товаре, которое приглашает его купить"},{"term":"Практика (practice)","def":"Когда мы делаем сами то, что изучили"},{"term":"Форум","def":"Встреча, где команды показывают проекты"},{"term":"Защита проекта","def":"Выступление с ответами на вопросы"},{"term":"Жюри","def":"Люди, которые оценивают выступления"},{"term":"Творческое задание","def":"Задание, где нужно придумать что-то своё"}],"english":"advertising — реклама; practice — практика","concepts":{"head":"Понятия","items":["Защита проекта — команда рассказывает о рекламе (advertising) и отвечает на вопросы.","Жюри оценивает по критериям: понятность, целевая аудитория, честность, креативность (по 0–3, всего 12).","Практика (practice) — сегодня делаем сами."]},"steps":{"head":"Как пройти форум, по шагам","items":["Доделать рекламу по черновику (15 минут)","Проверить по чек-листу: заголовок, картинка, цена, призыв","Репетиция защиты с таймером","Защита 2 минуты","Ответы на 2 вопроса: «Спасибо за вопрос. Мы думаем, что…»","Творческое задание — улучшить рекламу по совету жюри"]},"scheme":"Табло форума: строки — команды, столбцы — 4 критерия и «Итого». Ниже таймер 2:00 и образец ответа на вопрос.","examples":[{"lab":"Казахстан","text":"Команда рекламирует варежки из верблюжьей шерсти «Тёплая Дала» для школьников северных областей; слоган «Мороз не страшен!»; цена 900 тенге: материалы 400 + работа 300 + реклама 100 + прибыль 100. Жюри: понятность 3, ЦА 3, честность 3, креативность 2 — 11 баллов из 12."},{"lab":"Мир","text":"На фестивалях рекламы команды из разных стран защищают свои работы перед жюри и объясняют, почему их реклама сработала."}],"mistake":{"myth":"Команда спорит с жюри или отвечает «не знаем»","fix":"Потренировать фразы «Хороший вопрос, мы подумаем…», «Мы считаем, что…, потому что…»."},"check":[{"q":"Сколько максимум баллов?","a":"12"},{"q":"Как начать ответ жюри?","a":"«Спасибо за вопрос…»"},{"q":"400 + 300 + 100 + 100 = ?","a":"900 тенге"}],"kz":{"text":"Верблюжья шерсть в Казахстане — традиционный материал для тёплых вещей: из неё делают одеяла, носки и варежки, их продают на рынках и в магазинах.","link":"реклама товара края должна говорить правду о его свойствах."},"world":{"text":"На международных фестивалях рекламы команды со всего мира защищают свои работы, и лучшие награды часто получает социальная реклама, которая помогает людям.","link":""},"fact":"Шерсть верблюда хорошо сохраняет тепло, и кочевники Великой степи с давних времён делали из неё одеяла и одежду.","cards":[{"n":"1","title":"Чек-лист рекламы перед защитой","lines":["Заголовок или слоган (до 5 слов) — есть / нет","Одна главная картинка — есть / нет","Целевая аудитория понятна — да / нет","Цена (до 1000 тенге) и расчёт — есть / нет","Призыв и где купить — есть / нет","Нет обмана — да / нет"],"hand":"Сдать: отмеченный чек-лист.","answers":[]},{"n":"2","title":"Лист жюри","lines":["Команда: ____","Понятность (0–3): ___ ЦА (0–3): ___ Честность (0–3): ___ Креативность (0–3): ___","Итого: ___ из 12.","Вопрос команде: ____","Комплимент: ____ Совет: ____"],"hand":"Сдать: лист тренеру.","answers":[]}],"practice":[{"type":"scene","title":"Рекламный форум","minutes":8,"setting":"Настоящий форум: команды защищают рекламу перед жюри.","roles":[{"name":"Ведущий форума","task":"Объявляешь команды."},{"name":"Команда","task":"Защищаете рекламу."},{"name":"Жюри","task":"Задаёте вопрос и оцениваете."}],"steps":["Объявление.","Защита.","Вопрос жюри.","Оценка."],"freeze":["Стоп-кадр! Был ли ответ полным предложением?"],"twist":"Поворот: жюри спрашивает: «А для кого эта реклама?» Кто ответит?","debrief":["Что получилось лучше всего?"]},{"type":"scene","title":"Вопрос жюри","minutes":5,"setting":"Жюри задаёт трудный вопрос.","roles":[{"name":"Жюри","task":"Задаёшь вопрос."},{"name":"Ответчик","task":"Отвечаешь полным предложением."}],"steps":["Вопрос.","Ответ."],"freeze":["Стоп-кадр! Хороший ли ответ?"],"twist":null,"debrief":["Как отвечать жюри?"]},{"type":"scene","title":"Аплодисменты","minutes":4,"setting":"Каждая команда хвалит другую за одну вещь.","roles":[{"name":"Команда","task":"Говорите одну похвалу другой команде."},{"name":"Ведущий","task":"Даёшь слово каждой команде по очереди."}],"steps":["Похвала.","Аплодисменты."],"freeze":["Стоп-кадр! Что понравилось у соперников?"],"twist":null,"debrief":["Почему важно хвалить других?"]}],"homework":"Творческое задание: улучшить рекламу команды по совету жюри (нарисовать новую версию заголовка или картинки).","support":"Готовый чек-лист с картинками и роль показывающего плакат с одной фразой.","advanced":"Быть председателем жюри: следить за временем и подвести итог по табло.","photo":{"src":"lessons/img/03_29.jpg","author":"Product School","q":["Что вы видите на фото? Как это связано с нашей темой?","Какую рекламу из нашего форума вы показали бы детям в другой стране?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g03-l29.pptx","name":"29. Рекламный форум — практикум (3 кл).pptx","mb":1.5}},{"id":"03_30","g":3,"l":30,"topic":"Итоговая работа за полугодие","module":"Реклама","format":"Итоговая работа","skills":["Критическое мышление","Финансовое мышление"],"goal":"К концу урока ученик сможет самостоятельно выполнить итоговую работу: ответить на 10 вопросов теста по терминам рекламы и решить практическое задание — найти ошибку в рекламе, определить целевую аудиторию и посчитать бюджет до 1000 тенге.","criteria":["Я отвечаю на вопросы теста самостоятельно.","Я нахожу ошибку в рекламе и предлагаю исправление.","Я правильно считаю бюджет рекламы и проверяю работу по ключу."],"result":"Выполненная итоговая работа (тест из 10 вопросов + практическое задание из 3 частей), проверенная по ключу самопроверки.","stages":[{"stage":"Разминка «Правда или ловушка?»","min":4},{"stage":"Выполнение работы","min":28},{"stage":"Самопроверка","min":4},{"stage":"Рефлексия","min":4}],"warm":{"kind":"truth","name":"Правда или ловушка?","rules":["Учитель читает слово урока и объяснение — правильное или «перепутанное».","10 секунд молча решаем, так ли объясняется слово.","«Три-два-один!» — все сразу показывают: ладонь вверх = ПРАВДА, кулак = ЛОВУШКА."],"items":[{"term":"Реклама (advertising)","real":"Сообщение, которое приглашает купить товар или сделать доброе дело","shown":"Сообщение, которое приглашает купить товар или сделать доброе дело","truth":true,"first":"Р"},{"term":"Повторение (review)","real":"Когда мы вспоминаем изученное","shown":"Короткая запоминающаяся фраза о товаре","truth":false,"first":"П"},{"term":"Печатная реклама","real":"Реклама на бумаге: листовки, плакаты","shown":"Реклама на бумаге: листовки, плакаты","truth":true,"first":"П"},{"term":"Целевая аудитория","real":"Люди, для которых сделан товар","shown":"Когда мы вспоминаем изученное","truth":false,"first":"Ц"},{"term":"Социальная реклама","real":"Реклама, которая зовёт к доброму поведению","shown":"Реклама, которая зовёт к доброму поведению","truth":true,"first":"С"},{"term":"Слоган","real":"Короткая запоминающаяся фраза о товаре","shown":"Люди, для которых сделан товар","truth":false,"first":"С"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Реклама (advertising)","def":"Сообщение, которое приглашает купить товар или сделать доброе дело"},{"term":"Повторение (review)","def":"Когда мы вспоминаем изученное"},{"term":"Печатная реклама","def":"Реклама на бумаге: листовки, плакаты"},{"term":"Целевая аудитория","def":"Люди, для которых сделан товар"},{"term":"Социальная реклама","def":"Реклама, которая зовёт к доброму поведению"},{"term":"Слоган","def":"Короткая запоминающаяся фраза о товаре"},{"term":"Тираж","def":"Сколько одинаковых экземпляров напечатали"}],"english":"advertising — реклама; review — повторение","concepts":{"head":"Определения","items":["Реклама (advertising) — сообщение о товаре.","Печатная — листовки, плакаты; 3 правила: коротко, ярко, понятно, что делать.","Сюжетная реклама — история «герой — проблема — решение».","Целевая аудитория — для кого товар.","Реклама у блогера — признаки: надпись «Реклама», промокод, ссылка, много раз марка.","Коммерческая реклама продаёт, социальная — зовёт к доброму делу.","Слоган — фраза до 5 слов.","Тираж — число копий."]},"steps":{"head":"Как выполнять работу, по шагам","items":["Прочитай вопрос до конца","Выбери один ответ","В задаче запиши решение и ответ в тенге","Трудный вопрос пропусти и вернись","Проверь по ключу"]},"scheme":"Карта модуля: в центре «Реклама», лучи: «Печатная (3 правила)», «Сюжетная (герой — проблема — решение)», «ЦА», «Блогеры (признаки)», «Коммерческая / социальная», «Форум (4 критерия)».","examples":[{"lab":"Казахстан","text":"Листовка кружка: 150 копий по 4 тенге — 600 тенге. Социальная реклама Года волонтёра — зовёт помогать."},{"lab":"Мир","text":"Медведь Смоки в США — социальная реклама о лесе."}],"mistake":{"myth":"Путают коммерческую и социальную рекламу из-за логотипа компании","fix":"Смотрим на цель — продать или изменить поведение."},"check":[{"q":"Какие 3 правила листовки?","a":"Коротко, ярко, понятно, что делать"},{"q":"Признак рекламы у блогера?","a":"Надпись «Реклама», промокод, ссылка"},{"q":"200 листовок по 3 тенге?","a":"600 тенге"}],"kz":{"text":"Казахстан участвует в международном исследовании PISA, где школьники решают задания на понимание текста и финансовую грамотность, в том числе связанные с рекламой и покупками.","link":"умение спокойно разбирать рекламу и считать деньги — часть грамотности."},"world":{"text":"Во многих странах школьники учатся «медиаграмотности» — умению понимать рекламу и отличать её от обычной информации; ЮНЕСКО поддерживает такие программы по всему миру.","link":""},"fact":"ЮНЕСКО продвигает «медийную и информационную грамотность» и ежегодно в конце октября проводит Глобальную неделю медийной и информационной грамотности.","cards":[{"n":"1","title":"Тест (обведи один ответ)","lines":["1. Реклама — это: а) сообщение, которое приглашает купить или сделать что-то; б) любая картинка.","2. Правила листовки: а) коротко, ярко, понятно, что делать; б) длинно и мелко.","3. Части рекламной истории: а) герой, проблема, решение; б) цена, адрес, телефон.","4. Целевая аудитория — это: а) люди, для которых сделан товар; б) все люди мира.","5. Признак рекламы у блогера: а) промокод и надпись «Реклама»; б) блогер улыбается.","6. Социальная реклама: а) зовёт к доброму делу; б) продаёт товар.","7. «Купи сок за 300 тенге» — это: а) коммерческая реклама; б) социальная.","8. Слоган — это: а) короткая запоминающаяся фраза; б) цена товара.","9. Тираж — это: а) сколько копий напечатали; б) размер листа.","10. Критерии форума: а) понятность, ЦА, честность, креативность; б) кто громче."],"hand":"Сдать: тест.","answers":[]},{"n":"2","title":"Практическое задание","lines":["Реклама: «Наш магазин игрушек самый лучший в мире! Открыты с 9 до 18» — мелкий текст, нет адреса, повесили у автозаправки.","1) Найди 2 ошибки. 2) Кто целевая аудитория и где повесить? 3) Напечатали 150 листовок по 4 тенге. Сколько потратили? Хватит ли бюджета 1000 тенге и сколько останется?"],"hand":"Сдать: решение.","answers":[]},{"n":"3","title":"Ключ","lines":["Тест: все ответы «а» — по 1 баллу (10 баллов).","Практика: ошибки — нет адреса/непонятно, где купить; «самый лучший в мире» — неправда/неясно; не та ЦА (2 балла). ЦА — дети и родители, повесить у школы, в детском саду (1 балл). 150 × 4 = 600 тенге, остаток 400 тенге (2 балла).","Всего 15 баллов. Перевод в 1–10: 15–14 → 10; 13 → 9; 12 → 8; 11 → 7; 10 → 6; 9 → 5; 8 и меньше — 4 и ниже."],"hand":"Сдать: работу с баллами.","answers":[]}],"homework":"Не задаётся; по желанию — найти дома одну рекламу и определить её вид и целевую аудиторию.","support":"Тест с крупным шрифтом, картинками-подсказками и чтением вопросов вслух; таблица умножения для задачи.","advanced":"Дополнительное задание: придумать слоган для социальной рекламы школы и оценить его по 4 критериям форума.","photo":{"src":"lessons/img/03_30.jpg","author":"Vitaly Gariev","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему умение распознавать рекламу пригодится каждому человеку?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g03-l30.pptx","name":"30. Итоговая работа за полугодие (3 кл).pptx","mb":1.4}},{"id":"03_31","g":3,"l":31,"topic":"Работа над ошибками и обратная связь по итоговой работе","module":"Реклама","format":"Итоговая работа","skills":["Критическое мышление","Финансовое мышление"],"goal":"К концу урока ученик сможет найти свои ошибки в итоговой работе, исправить их с объяснением правила и решить по одному похожему заданию на каждую тему, где ошибся.","criteria":["Я нахожу и исправляю свои ошибки.","Я объясняю правило, по которому исправил.","Я решаю похожее задание и принимаю обратную связь тренера."],"result":"Лист работы над ошибками: исправления с объяснением «Правильно так, потому что…» и решённые похожие задания.","stages":[{"stage":"Разминка «Угадай слово»","min":4},{"stage":"Выполнение работы","min":28},{"stage":"Самопроверка","min":4},{"stage":"Рефлексия","min":4}],"warm":{"kind":"guess","name":"Угадай слово","rules":["Слово спрятано — звучит только его объяснение и первая буква.","10 секунд команда шёпотом выбирает одно слово.","«Три-два-один!» — все команды хором называют слово. Верно — балл команде."],"items":[{"term":"Ошибка (mistake)","real":"Неправильный ответ, который показывает, что нужно повторить","shown":"Неправильный ответ, который показывает, что нужно повторить","truth":true,"first":"О"},{"term":"Обратная связь (feedback)","real":"Подсказка тренера или друга: что получилось и что улучшить","shown":"Сколько одинаковых экземпляров напечатали","truth":false,"first":"О"},{"term":"Исправление","real":"Правильный ответ вместо ошибки с объяснением","shown":"Правильный ответ вместо ошибки с объяснением","truth":true,"first":"И"},{"term":"Целевая аудитория","real":"Люди, для которых сделан товар","shown":"Подсказка тренера или друга: что получилось и что улучшить","truth":false,"first":"Ц"},{"term":"Социальная реклама","real":"Реклама, которая зовёт к доброму делу","shown":"Реклама, которая зовёт к доброму делу","truth":true,"first":"С"},{"term":"Тираж","real":"Сколько одинаковых экземпляров напечатали","shown":"Люди, для которых сделан товар","truth":false,"first":"Т"}],"perm":[3,2,1,0,5,4]},"glossary":[{"term":"Ошибка (mistake)","def":"Неправильный ответ, который показывает, что нужно повторить"},{"term":"Обратная связь (feedback)","def":"Подсказка тренера или друга: что получилось и что улучшить"},{"term":"Исправление","def":"Правильный ответ вместо ошибки с объяснением"},{"term":"Целевая аудитория","def":"Люди, для которых сделан товар"},{"term":"Социальная реклама","def":"Реклама, которая зовёт к доброму делу"},{"term":"Тираж","def":"Сколько одинаковых экземпляров напечатали"}],"english":"mistake — ошибка; feedback — обратная связь","concepts":{"head":"Понятия","items":["Ошибка (mistake) — подсказка, что повторить.","Обратная связь (feedback) — что получилось и что улучшить.","Работа над ошибками: найти → понять правило → исправить → потренироваться."]},"steps":{"head":"Как работать, по шагам","items":["Найди задание с отметкой","Перечитай вопрос","Найди правило в «памятке модуля»","Запиши правильный ответ","Объясни: «Правильно так, потому что…»","Реши похожее задание из Карточки 2"]},"scheme":"«Памятка модуля»: 3 правила листовки; герой — проблема — решение; ЦА — «для кого?»; признаки рекламы у блогера; коммерческая = продать, социальная = доброе дело; тираж × цена копии = расходы.","examples":[{"lab":"Казахстан","text":"Ученик написал: «“Пристегнись!” — коммерческая реклама, потому что на плакате логотип автосалона». Исправление: цель — безопасность людей, значит, социальная; автосалон показывает социальную ответственность. Ошибка в"},{"lab":"Расчёте","text":"«150 листовок по 4 тенге = 154 тенге» — сложили вместо умножения; правильно 150 × 4 = 600 тенге."},{"lab":"Мир","text":"В компаниях по всему миру после рекламной кампании проводят «разбор»: что сработало, что нет, и записывают уроки."}],"mistake":{"myth":"Переписать ответ с доски, не поняв почему","fix":"Каждое исправление — с фразой «потому что», и похожее задание без подсказки."},"check":[{"q":"Чем определяется вид рекламы — логотипом или целью?","a":"Целью"},{"q":"120 копий по 5 тенге?","a":"600 тенге"},{"q":"Что делать после исправления?","a":"Решить похожее задание"}],"kz":{"text":"Казахстанские шахматисты, например чемпионка мира по блицу Бибисара Асаубаева, после каждой партии разбирают свои ошибки с тренером.","link":"разбор ошибок — путь к победе."},"world":{"text":"Во многих компаниях мира после каждого проекта проводят разбор: что получилось и чему научились. Например, после «новой колы» в 1985 году компания Coca-Cola признала ошибку и вернула старый вкус.","link":""},"fact":"В 1985 году компания Coca-Cola заменила вкус своего напитка, а через 79 дней вернула прежний из-за недовольства покупателей; эту историю часто приводят как пример признания ошибки.","cards":[{"n":"1","title":"Работа над ошибками","lines":["Номер задания: ___ Мой","Правило: ___","Правильно так, потому что: ___","(Повтори для каждой ошибки.)"],"hand":"Сдать: лист.","answers":[["","___ Правильный ответ: ___"]]},{"n":"2","title":"Похожие задания","lines":["1. «Сдай макулатуру — спаси дерево» — какая реклама?","2. Назови целевую аудиторию рекламы кружка шахмат для 3 класса. (Третьеклассники и их родители.)","3. 120 копий по 5 тенге. Сколько стоит тираж?","4. Найди ошибку: листовка без цены и адреса. (Непонятно, что делать.)","5. Назови 3 части рекламной истории. (Герой, проблема, решение.)"],"hand":"Сдать: ответы.","answers":[["","Социальная."],["","600 тенге."]]},{"n":"3","title":"Ключ для взаимопроверки","lines":["Ответы Карточки 2: социальная; третьеклассники и родители; 600 тенге; нет цены и адреса — непонятно, что делать; герой, проблема, решение.","Проверь: у каждого исправления есть «потому что»."],"hand":"Сдать: подпись проверяющего.","answers":[]}],"homework":"Решить задачу: 250 листовок по 3 тенге — сколько стоит тираж и хватит ли 800 тенге? (Ответ: 750 тенге, хватит, останется 50.)","support":"Памятка на парте, задания с готовым началом решения, работа с тренером.","advanced":"Составить для одноклассника своё задание «найди ошибку в рекламе» и ключ к нему.","photo":{"src":"lessons/img/03_31.jpg","author":"lilartsy","q":["Что вы видите на фото? Как это связано с нашей темой?","Почему важно признавать ошибки, а не скрывать их?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g03-l31.pptx","name":"31. Работа над ошибками и обратная связь по итоговой работе (3 кл).pptx","mb":1.4}},{"id":"03_32","g":3,"l":32,"topic":"Игра-повторение по темам полугодия","module":"Реклама","format":"Деловая игра","skills":["Командная работа","Креативность","Финансовое мышление"],"goal":"К концу урока ученик сможет в командной игре «Рекламное агентство» применить понятия модуля — виды рекламы, целевая аудитория, признаки рекламы у блогера, бюджет — и исправить ошибки в темах, где ошибался в итоговой работе.","criteria":["Я правильно применяю понятия модуля в ответах.","Я считаю бюджет рекламы в пределах 1000 тенге.","Я помогаю команде и играю честно."],"result":"Табло команды с баллами за 2 раунда и «заказ клиента», выполненный в раунде 2: реклама для заданного товара с ЦА, слоганом и бюджетом до 1000 тенге.","stages":[{"stage":"Разминка «Найди пару»","min":4},{"stage":"Инструктаж","min":4},{"stage":"Раунд 1","min":10},{"stage":"Раунд 2","min":10},{"stage":"Разбор","min":8},{"stage":"Рефлексия","min":4}],"warm":{"kind":"match","name":"Найди пару","rules":["На экране определения под номерами.","Учитель называет слово, например: «Слово А — …». 10 секунд на поиск.","Все одновременно показывают номер подходящего определения на пальцах."],"items":[{"term":"Повторение (review)","real":"Когда мы вспоминаем изученное","shown":"Когда мы вспоминаем изученное","truth":true,"first":"П"},{"term":"Игра (game)","real":"Занятие по правилам","shown":"Люди, для которых сделан товар","truth":false,"first":"И"},{"term":"Рекламное агентство","real":"Компания, которая делает рекламу для других компаний","shown":"Компания, которая делает рекламу для других компаний","truth":true,"first":"Р"},{"term":"Клиент агентства","real":"Компания, которая заказывает рекламу","shown":"Занятие по правилам","truth":false,"first":"К"},{"term":"Бюджет","real":"Сколько денег можно потратить","shown":"Сколько денег можно потратить","truth":true,"first":"Б"},{"term":"Целевая аудитория","real":"Люди, для которых сделан товар","shown":"Компания, которая заказывает рекламу","truth":false,"first":"Ц"}],"perm":[1,2,3,4,5,0]},"glossary":[{"term":"Повторение (review)","def":"Когда мы вспоминаем изученное"},{"term":"Игра (game)","def":"Занятие по правилам"},{"term":"Рекламное агентство","def":"Компания, которая делает рекламу для других компаний"},{"term":"Клиент агентства","def":"Компания, которая заказывает рекламу"},{"term":"Бюджет","def":"Сколько денег можно потратить"},{"term":"Целевая аудитория","def":"Люди, для которых сделан товар"}],"english":"review — повторение; game — игра","concepts":{"head":"Понятия модуля","items":["Реклама бывает печатная (3 правила: коротко, ярко, понятно, что делать), сюжетная (герой — проблема — решение), в интернете у блогеров (признаки: «Реклама», промокод, ссылка), коммерческая (продать) и социальная (доброе дело).","Целевая аудитория — для кого.","Рекламное агентство делает рекламу по заказу клиента и укладывается в бюджет."]},"steps":{"head":"Как устроена игра, по шагам","items":["Шаг 1: команды — рекламные агентства","Раунд 1 «Блиц»: вопросы по 1–3 балла из табло","Раунд 2 «Заказ клиента»: команда получает товар и бюджет, за 8 минут делает эскиз рекламы, определяет ЦА, слоган и считает расходы","Шаг 3: жюри оценивает по 4 критериям форума"]},"scheme":"Табло 5 × 3: категории «Печатная», «Истории», «ЦА», «Блогеры», «Социальная»; строки 1, 2, 3 балла. Справа — бланк заказа: «Товар — ЦА — Вид рекламы — Слоган — Бюджет».","examples":[{"lab":"Казахстан","text":"Заказ «Кафе национальной кухни в Туркестане хочет больше туристов. Бюджет 1000 тенге». Решение: ЦА — туристы у мавзолея Ходжи Ахмеда Ясави; листовки 100 штук по 5 тенге = 500 тенге, плакат = 300 тенге, всего 800 тенге, остаток 200. Слоган: «Попробуй вкус Туркестана!»."},{"lab":"Мир","text":"Крупные рекламные агентства работают для компаний в разных странах и меняют рекламу под каждую страну."}],"mistake":{"myth":"Команда тратит весь бюджет на один плакат и не считает остаток","fix":"Правило «сначала план расходов, потом эскиз»."},"check":[{"q":"Что делает рекламное агентство?","a":"Делает рекламу по заказу клиента"},{"q":"100 листовок по 5 тенге + плакат 300 тенге?","a":"800 тенге"},{"q":"Для кого реклама кафе у мавзолея?","a":"Для туристов"}],"kz":{"text":"Мавзолей Ходжи Ахмеда Ясави в Туркестане — объект Всемирного наследия ЮНЕСКО, куда приезжает много туристов; вокруг работают кафе, гостиницы, сувенирные лавки.","link":"бизнесам рядом нужна реклама для туристов."},"world":{"text":"Крупные рекламные агентства работают одновременно для компаний во многих странах и меняют рекламу под язык и традиции каждой страны.","link":""},"fact":"Мавзолей Ходжи Ахмеда Ясави внесён в список Всемирного наследия ЮНЕСКО в 2003 году и стал первым объектом Казахстана в этом списке.","cards":[{"n":"1","title":"Правила «Рекламного агентства»","lines":["Роли: капитан, художник, автор слогана, бухгалтер.","Раунд 1: выбирай вопрос за 1, 2 или 3 балла, 20 секунд на совет.","Раунд 2: выполни заказ клиента за 8 минут; жюри оценивает понятность, ЦА, честность, креативность (0–3)."],"hand":"Сдать: табло команды.","answers":[]},{"n":"2","title":"Вопросы блица (для тренера)","lines":["Печатная (1): 3 правила листовки? — Коротко, ярко, понятно, что делать.","Печатная (3): 200 листовок по 4 тенге? — 800 тенге.","Истории (2): части рекламной истории? — Герой, проблема, решение.","ЦА (2): ЦА рекламы самоката? — Дети 7–12 лет и их родители.","Блогеры (2): 2 признака рекламы? — Надпись «Реклама», промокод/ссылка.","Социальная (1): «Береги воду» — какая реклама? — Социальная.","Социальная (3): цель коммерческой и социальной? — Продать / изменить поведение."],"hand":"Сдать: отметки баллов.","answers":[]},{"n":"3","title":"Заказы клиентов (бюджет 1000 тенге)","lines":["А. Кафе национальной кухни в Туркестане хочет больше туристов.","Б. Кружок робототехники ищет учеников 3–4 классов.","В. Магазин варежек из верблюжьей шерсти перед зимой.","Г. Школа хочет, чтобы ученики сортировали мусор (социальная).","Цены: листовка — 5 тенге, плакат — 300 тенге, мини-ролик — 600 тенге.","Пример решения А: 100 листовок (500) + плакат (300) = 800, остаток 200."],"hand":"Сдать: эскиз, ЦА, слоган и расчёт.","answers":[]}],"practice":[{"type":"scene","title":"Рекламная викторина","minutes":6,"setting":"Команды отвечают на вопросы о рекламе.","roles":[{"name":"Ведущий","task":"Задаёшь вопрос."},{"name":"Команды","task":"Отвечаете по очереди."}],"steps":["Вопрос.","Ответ."],"freeze":["Стоп-кадр! Верно ли?"],"twist":null,"debrief":["Что мы знаем о рекламе?"]},{"type":"scene","title":"Бюджет 1000 тенге","minutes":5,"setting":"Командам нужно уложить рекламу в 1000 тенге.","roles":[{"name":"Бухгалтер","task":"Считаешь расходы."},{"name":"Капитан","task":"Решаешь, что оставить."}],"steps":["Расходы.","Выбор."],"freeze":["Стоп-кадр! Уложились?"],"twist":null,"debrief":["Как планировать бюджет рекламы?"]}],"homework":"Придумать заказ для рекламного агентства (товар, ЦА, бюджет до 1000 тенге) и решить его самому.","support":"Шпаргалка понятий для команды и вопросы за 1 балл с картинками.","advanced":"Выполнить «срочный заказ»: социальную рекламу для школы с бюджетом 500 тенге.","photo":{"src":"lessons/img/03_32.jpg","author":"National Cancer Institute","q":["Что вы видите на фото? Как это связано с нашей темой?","Что нужно изменить в рекламе казахского кафе, чтобы она понравилась туристам из Японии?"]},"deck":{"url":"https://github.com/omarumarov1-png/qsbi-quiz/releases/download/slides-q2/qsbi-g03-l32.pptx","name":"32. Игра-повторение по темам полугодия (3 кл).pptx","mb":1.5}}];
